function [np, nf] = test_phase5b_registry()
%TEST_PHASE5B_REGISTRY  Phase-5b Task C2 CT correction + registry v2 tests.
%   Asserts the locked v2 interface over study rows (physical rows arrive in
%   C7, same function): GSUT-HV-51 + GIS-Q0-51 at 1600/1 SOURCE-BACKED with
%   ledger provenance (GIS-bay-1600/1, GSUT-1600/1-cores); GEN CTs unchanged
%   at 15000/1; zero ct_ratio==2000 / zero ==16000 anywhere; study-row TMS
%   0.20; GEN-51-SI pickup NaN + RULE-1.2xMAXLOAD tag (C4 recomputes, never
%   hard-coded here); gen.Imax_A 14309; topology breaker_52G 10BAC10 +
%   rating_100kA; layer in PHYSICAL/STUDY; 16k scope gen-only via
%   phase5b_ct_scope.
T = t_case('test_phase5b_registry');
R = phase5b_registry();
% --- Locked interface: struct with devices/gen/topology ---
T = T.chk(isstruct(R)&&isfield(R,'devices')&&isfield(R,'gen')&&isfield(R,'topology'), 'registry struct with devices/gen/topology');
% --- Locked device fields: v1 21 + physical_CT_ratio, selected_CT_core, protection_function, study_CT_ratio, layer = 26 ---
v1f = {'device_id','device_type','equipment','ansi','zone','ct_ratio','ct_source','rated_A','vnom_kV','fault_source','pickup_A','tms','curve','ef_pickup_A','ef_tms','breaker_ref','upstream','downstream','provenance','status','assumption_class'};
newf = {'physical_CT_ratio','selected_CT_core','protection_function','study_CT_ratio','layer'};
T = T.chk(isequal(sort(fieldnames(R.devices)'),sort([v1f newf])), 'devices struct has locked 26 fields (21 v1 + 5 v2)');
T = T.chk(isfield(R.devices,'physical_CT_ratio')&&isfield(R.devices,'study_CT_ratio'), 'physical_CT_ratio/study_CT_ratio columns present');
T = T.chk(isfield(R.devices,'selected_CT_core')&&isfield(R.devices,'protection_function'), 'selected_CT_core/protection_function columns present');
% --- 7 v1 study rows carried (C7 appends physical rows; allow growth) ---
ids = {R.devices.device_id};
T = T.chk(numel(R.devices) >= 7, '7 v1 study rows minimum');
need_ids = {'GEN-51','GEN-51N','GSUT-HV-51','GIS-Q0-51','GIS-Q0-50','LINE-21-note','REMOTE-GRID-boundary'};
for k = 1:numel(need_ids)
    T = T.chk(any(strcmp(ids,need_ids{k})), ['device present: ' need_ids{k}]);
end
% --- layer in PHYSICAL/STUDY; C2 study rows all STUDY ---
for i = 1:numel(R.devices)
    T = T.chk(strcmp(R.devices(i).layer,'STUDY')||strcmp(R.devices(i).layer,'PHYSICAL'), ['layer whitelisted: ' R.devices(i).device_id]);
end
study_ids = {R.devices(strcmp({R.devices.layer},'STUDY')).device_id};
for k = 1:numel(need_ids)
    T = T.chk(any(strcmp(study_ids,need_ids{k})), ['study layer: ' need_ids{k}]);
end
% --- S4 CT correction: GSUT-HV-51 + GIS-Q0-51 at 1600/1 SOURCE-BACKED ---
g = R.devices(strcmp(ids,'GSUT-HV-51'));
T = T.chk(g.ct_ratio == 1600, 'GSUT-HV-51 ct_ratio 1600');
T = T.chk(strcmp(g.ct_source,'SOURCE-BACKED'), 'GSUT-HV-51 ct_source SOURCE-BACKED');
T = T.chk(~isempty(strfind(g.provenance,'GSUT-1600/1-cores')), 'GSUT provenance refs GSUT-1600/1-cores ledger');
q = R.devices(strcmp(ids,'GIS-Q0-51'));
T = T.chk(q.ct_ratio == 1600, 'GIS-Q0-51 ct_ratio 1600');
T = T.chk(strcmp(q.ct_source,'SOURCE-BACKED'), 'GIS-Q0-51 ct_source SOURCE-BACKED');
T = T.chk(~isempty(strfind(q.provenance,'GIS-bay-1600/1')), 'GIS provenance refs GIS-bay-1600/1 ledger');
% --- Physical/study CT columns agree with corrected ratios ---
T = T.chk(g.physical_CT_ratio == 1600 && g.study_CT_ratio == 1600, 'GSUT physical/study CT 1600');
T = T.chk(q.physical_CT_ratio == 1600 && q.study_CT_ratio == 1600, 'GIS-Q0 physical/study CT 1600');
% --- Function-core mapping NOT DETERMINABLE where bay-dependent (S4) ---
T = T.chk(~isempty(strfind(g.selected_CT_core,'NOT-DETERMINABLE')), 'GSUT core mapping NOT-DETERMINABLE bay-dependent');
T = T.chk(~isempty(strfind(q.selected_CT_core,'NOT-DETERMINABLE')), 'GIS-Q0 core mapping NOT-DETERMINABLE bay-dependent');
% --- GEN CTs 15000/1 unchanged ---
p51 = R.devices(strcmp(ids,'GEN-51'));
T = T.chk(p51.ct_ratio == 15000 && strcmp(p51.ct_source,'SOURCE-BACKED'), 'GEN-51 CT 15000/1 unchanged');
T = T.chk(p51.physical_CT_ratio == 15000 && p51.study_CT_ratio == 15000, 'GEN-51 physical/study CT 15000');
p51n = R.devices(strcmp(ids,'GEN-51N'));
T = T.chk(p51n.ct_ratio == 15000 && strcmp(p51n.ct_source,'SOURCE-BACKED'), 'GEN-51N CT 15000/1 unchanged');
% --- Zero blanket ratios anywhere: no 2000, no 16000 ---
ratios = [R.devices.ct_ratio];
T = T.chk(~any(ratios == 2000), 'zero devices with ct_ratio 2000');
T = T.chk(~any(ratios == 16000), 'zero devices with ct_ratio 16000');
T = T.chk(~any([R.devices.physical_CT_ratio] == 2000 | [R.devices.study_CT_ratio] == 2000), 'zero physical/study CT 2000');
T = T.chk(~any([R.devices.physical_CT_ratio] == 16000 | [R.devices.study_CT_ratio] == 16000), 'zero physical/study CT 16000');
% --- Study-row TMS 0.20 (setting-capable study rows; notes stay NaN) ---
capable = {'GEN-51','GEN-51N','GSUT-HV-51','GIS-Q0-51','GIS-Q0-50'};
for k = 1:numel(capable)
    d = R.devices(strcmp(ids,capable{k}));
    T = T.chk(isscalar(d) && strcmp(d.layer,'STUDY') && d.tms == 0.20, ['study TMS 0.20: ' capable{k}]);
end
ln = R.devices(strcmp(ids,'LINE-21-note'));
T = T.chk(isnan(ln.tms), 'LINE-21-note TMS stays NaN');
rb = R.devices(strcmp(ids,'REMOTE-GRID-boundary'));
T = T.chk(isnan(rb.tms), 'REMOTE-GRID-boundary TMS stays NaN');
% --- GEN-51-SI pickup NaN + RULE-1.2xMAXLOAD tag (C4 recomputes) ---
T = T.chk(isnan(p51.pickup_A), 'GEN-51-SI pickup NaN (C4 recomputes)');
T = T.chk(~isempty(strfind(p51.protection_function,'RULE-1.2xMAXLOAD')), 'GEN-51-SI rule tag RULE-1.2xMAXLOAD');
T = T.chk(isnan(p51n.pickup_A) && isnan(g.pickup_A) && isnan(q.pickup_A), 'study OC pickups all NaN (never hard-coded)');
% --- v1 values copied except CT/TMS/new columns ---
T = T.chk(p51.rated_A == 12019 && p51.vnom_kV == 22, 'GEN-51 rated values copied');
T = T.chk(g.rated_A == 1150 && g.vnom_kV == 230, 'GSUT-HV-51 rated values copied');
T = T.chk(q.rated_A == 2000 && q.vnom_kV == 230, 'GIS-Q0-51 rated values copied');
T = T.chk(strcmp(q.breaker_ref,'Q0'), 'GIS-Q0-51 keeps Q0 breaker_ref');
% --- gen adds Imax_A 14309; v1 gen preserved ---
T = T.chk(R.gen.Snom_MVA == 458 && R.gen.Vnom_kV == 22 && R.gen.Irated_A == 12019 && R.gen.pf == 0.85, 'gen v1 values preserved');
T = T.chk(R.gen.Imax_A == 14309, 'gen Imax_A 14309');
% --- topology adds breaker_52G 10BAC10 + rating_100kA; v1 topology preserved ---
T = T.chk(strcmp(R.topology.Q0,'breaker'), 'topology Q0 breaker preserved');
T = T.chk(strcmp(R.topology.Q1,'disconnector')&&strcmp(R.topology.Q2,'disconnector')&&strcmp(R.topology.Q9,'disconnector'), 'topology Q1/Q2/Q9 disconnectors preserved');
T = T.chk(strcmp(R.topology.Q51,'earthing')&&strcmp(R.topology.Q52,'earthing')&&strcmp(R.topology.Q8,'earthing'), 'topology Q51/Q52/Q8 earthing preserved');
T = T.chk(strcmp(R.topology.breaker_52G,'10BAC10'), 'topology breaker_52G 10BAC10');
T = T.chk(R.topology.rating_100kA == 100, 'topology rating_100kA 100');
% --- Legacy CT reference fenced (never substituted into devices) ---
T = T.chk(R.ct_primary == 15000 && R.ct_legacy == 16000, 'CT ledger 15000 primary / 16000 legacy reference');
% --- Sensitivity scope: 16k applies to generator CT only ---
T = T.chk(phase5b_ct_scope('GEN-51') == true, 'scope GEN-51 true');
T = T.chk(phase5b_ct_scope('GEN-51N') == true, 'scope GEN-51N true (generator CT)');
T = T.chk(phase5b_ct_scope('GSUT-HV-51') == false, 'scope GSUT-HV-51 false');
T = T.chk(phase5b_ct_scope('GIS-Q0-51') == false, 'scope GIS-Q0-51 false');
T = T.chk(phase5b_ct_scope('GIS-Q0-50') == false, 'scope GIS-Q0-50 false');
T = T.chk(phase5b_sensitivity_scope('GEN-51') == true, 'plan-name wrapper GEN-51 true');
T = T.chk(phase5b_sensitivity_scope('GIS-Q0-51') == false, 'plan-name wrapper GIS-Q0-51 false');
% --- Provenance tagged (v1 whitelist + C7 USER_ASSERTED_PENDING_DOC for physical baseline/87G) ---
allowed_prov = {'SOURCE-BACKED','DERIVED','ENGINEERING_ASSUMPTION','LEGACY','MISSING','USER_ASSERTED_PENDING_DOC'};
for i = 1:numel(R.devices)
    pv = R.devices(i).provenance;
    ok = false;
    for j = 1:numel(allowed_prov)
        if strncmp(pv, allowed_prov{j}, numel(allowed_prov{j}))
            ok = true; break;
        end
    end
    T = T.chk(ok, ['provenance tagged: ' R.devices(i).device_id]);
end
% --- No manufacturer / model strings in STUDY rows (C2 intent: no invented
% manufacturer settings in the coordination study; C7 PHYSICAL presence rows
% legitimately reference ledger relay types 7UT6331/7SS523/7SD5221/6MD66 +
% SIEMENS ledger ids + 10BAC10 with SOURCE-BACKED/USER_ASSERTED provenance
% and are asserted explicitly in test_phase5b_zones, so exempt here) ---
forbidden = {'siemens','abb','sel-','general electric','alstom','micom','7um','7sa','7sj','7ut','rel5','ret5','manufacturer','model number'};
strfields = {'device_id','device_type','equipment','ansi','zone','ct_source','fault_source','curve','breaker_ref','upstream','downstream','provenance','status','assumption_class','selected_CT_core','protection_function','layer'};
for i = 1:numel(R.devices)
    if strcmp(R.devices(i).layer,'PHYSICAL')
        T = T.chk(true, ['physical relay-type refs allowed (zones-asserted): ' R.devices(i).device_id]);
        continue;
    end
    blob = '';
    for f = 1:numel(strfields)
        v = R.devices(i).(strfields{f});
        if ischar(v), blob = [blob ' ' lower(v)]; end
    end
    hit = false;
    for b = 1:numel(forbidden)
        if ~isempty(strfind(blob, forbidden{b})), hit = true; break; end
    end
    T = T.chk(~hit, ['no manufacturer/model strings: ' R.devices(i).device_id]);
end
% --- Errors phase5b-prefixed ---
try
    phase5b_registry(1);
    T = T.chk(false, 'phase5b_registry(1) errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'registry error phase5b-prefixed');
end
try
    phase5b_ct_scope();
    T = T.chk(false, 'phase5b_ct_scope() errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'scope error phase5b-prefixed');
end
[np, nf] = T.done();
end

function [np, nf] = test_phase5b_pickup()
%TEST_PHASE5B_PICKUP  Phase-5b Tasks C3+C4 pickup tests (Ashuganj South, MATLAB).
%   C3 Siemens DT baseline layer (PHYSICAL GEN-51-SIEMENS-BL, ansi 50/51-DT,
%   provenance USER_ASSERTED_PENDING_DOC): setting 17171 A +-0.5% (cross-check
%   computed INSIDE this test), secondary 1.1447 A +-0.5%, tdef 3.00 s with
%   time_status NOT-DETERMINABLE-??-PENDING-COORDINATION, curve DT-?? with
%   use_phase5_time false (inverse prohibited: phase5_time/phase5_curve must
%   error, refused by contract). STUDY/PHYSICAL separation via live
%   phase5b_registry (GEN-51 variant layer STUDY, distinct id).
%   C4 study rules (all rows live from phase5b_registry): GEN-51-SI =
%   1.20x14309 = 17170.8 A (max-operating-current basis; converges with the
%   Siemens 17171 A baseline, characteristic differs SI vs DT); GSUT-HV-51 =
%   1.2xmax(1150, 870.7726) = 1380 A via 1600/1; GIS-Q0-51 = 1.2x869.956652
%   via 1600/1; GEN-51N-SI-STUDY = 5 A retained sensitive case (scope
%   SENSITIVITY); TMS 0.20 all study PHASE rows, EF TMS 0.15 per master S21;
%   GIS-Q0-50 stays DISABLED (phase5b_pickup:disabled; TMS never enables it).
%   The baseline device struct below mirrors the future C7 registry row
%   field-for-field (26 v2 fields); C7 must carry GEN-51-SIEMENS-BL with
%   these values and C12 re-asserts via the registry. Non-served ids error
%   with phase5b prefix (no stub behavior by design).
T = t_case('test_phase5b_pickup');
% Frozen anchors (PRIMARY A; same convention as test_phase5_pickup):
% GEN_Q frozen flow 9.47574312698307 kA; min phase fault F3 LL 43758.8597559 A.
FL_GENQ_A = 9.47574312698307 * 1000;
IMIN_PHASE_A = 43758.8597559;
% --- Baseline device shape (C7 registry contract, constructed here) ---
dev = siemens_baseline_device();
T = T.chk(strcmp(dev.device_id, 'GEN-51-SIEMENS-BL'), 'baseline device id GEN-51-SIEMENS-BL');
T = T.chk(strcmp(dev.ansi, '50/51-DT'), 'baseline ansi 50/51-DT');
T = T.chk(strcmp(dev.layer, 'PHYSICAL'), 'baseline layer PHYSICAL');
T = T.chk(strncmp(dev.provenance, 'USER_ASSERTED_PENDING_DOC', 25), 'baseline provenance USER_ASSERTED_PENDING_DOC');
% --- Locked interface: v1 fields + tdef/time_status/curve/use_phase5_time/secondary ---
P = phase5b_pickup(dev, FL_GENQ_A, IMIN_PHASE_A);
T = T.chk(isstruct(P) && all(isfield(P, {'setting', 'unit', 'basis', 'source', ...
    'validation', 'device_id', 'assumption_class', 'tdef', 'time_status', ...
    'curve', 'use_phase5_time', 'setting_sec_A'})), 'locked interface: v1 fields + tdef/time_status/curve/use_phase5_time/setting_sec_A');
T = T.chk(strcmp(P.device_id, 'GEN-51-SIEMENS-BL'), 'pickup echoes baseline device id');
% --- Setting 17171 A primary (+-0.5% band) ---
T = T.chk(abs(P.setting - 17171) / 17171 < 0.005, 'baseline setting 17171 A primary +-0.5%');
% --- Cross-check INSIDE test: 1.2xImax-14309 = 17170.8 ~ 17171 ---
T = T.chk(abs(1.2 * 14309 - 17171) / 17171 < 0.005, 'cross-check abs(1.2*14309-17171)/17171 < 0.005');
% --- Secondary 1.1447 A (+-0.5%) + CT consistency ---
T = T.chk(abs(P.setting_sec_A - 1.1447) / 1.1447 < 0.005, 'secondary 1.1447 A +-0.5%');
T = T.chk(abs(P.setting_sec_A - P.setting / 15000) / P.setting_sec_A < 1e-12, 'secondary consistency Is_sec = Is/15000');
% --- Definite time + NOT-DETERMINABLE timing ---
T = T.chk(abs(P.tdef - 3.00) < 1e-12, 'tdef 3.00 s');
T = T.chk(strcmp(P.time_status, 'NOT-DETERMINABLE-??-PENDING-COORDINATION'), 'time_status NOT-DETERMINABLE-??-PENDING-COORDINATION');
T = T.chk(strcmp(P.curve, 'DT-??'), 'curve DT-??');
T = T.chk(islogical(P.use_phase5_time) && isscalar(P.use_phase5_time) && ~P.use_phase5_time, 'use_phase5_time false (inverse prohibited)');
T = T.chk(strcmp(char(P.unit), 'A-primary'), 'pickup unit A-primary');
T = T.chk(~isempty(strfind(P.source, 'USER_ASSERTED_PENDING_DOC')), 'source carries USER_ASSERTED_PENDING_DOC');
% --- Inverse prohibited: phase5_time/phase5_curve must never take this row ---
try
    phase5_time(2 * P.setting_sec_A, P.setting_sec_A, P.tdef, P.curve);
    T = T.chk(false, 'phase5_time refuses DT-?? curve');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5', 6), 'phase5_time dispatch refused by contract (phase5-prefixed error)');
end
try
    phase5_curve(2.0, P.curve, 0.20);
    T = T.chk(false, 'phase5_curve refuses DT-?? family');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5', 6), 'phase5_curve dispatch refused by contract (phase5-prefixed error)');
end
% --- STUDY/PHYSICAL separation: GEN-51-SI variant row stays STUDY ---
R = phase5b_registry();
ids = {R.devices.device_id};
g = R.devices(strcmp(ids, 'GEN-51'));
T = T.chk(strcmp(g.layer, 'STUDY'), 'GEN-51-SI variant layer STUDY (separated from PHYSICAL baseline)');
T = T.chk(~strcmp(g.device_id, dev.device_id), 'variant device id distinct from baseline id');
% --- C4 study rule branch (Task C4: pickup/TMS re-baseline, study rules) ---
%   GEN-51-SI = 1.20xImax-14309 = 17170.8 A (max-operating-current basis;
%   converges with Siemens DT baseline 17171 A, characteristic differs SI
%   vs DT); GSUT-HV-51 = 1.2xmax(1150, 870.7726) = 1380 A via 1600/1;
%   GIS-Q0-51 = 1.2x869.956652 via 1600/1; GEN-51N-SI-STUDY = 5 A retained
%   sensitive case (scope SENSITIVITY); TMS 0.20 all study PHASE rows, EF
%   TMS 0.15 per master S21 (ledger EF-TMS-0.15). GIS-Q0-50 stays DISABLED
%   (registry TMS never enables it). All rows live from phase5b_registry.
Pg = phase5b_pickup(g, FL_GENQ_A, IMIN_PHASE_A);
T = T.chk(abs(Pg.setting - 17170.8) / 17170.8 < 1e-9, 'C4 GEN-51-SI setting 1.20x14309=17170.8 A');
T = T.chk(abs(Pg.tms - 0.20) < 1e-12, 'C4 GEN-51-SI TMS 0.20');
T = T.chk(strcmp(Pg.curve, 'SI'), 'C4 GEN-51-SI curve SI (study; differs from DT baseline)');
T = T.chk(islogical(Pg.use_phase5_time) && isscalar(Pg.use_phase5_time) && Pg.use_phase5_time, 'C4 GEN-51-SI use_phase5_time true (inverse allowed)');
T = T.chk(abs(Pg.setting_sec_A - Pg.setting / 15000) / Pg.setting_sec_A < 1e-12, 'C4 GEN-51-SI secondary Is/15000');
T = T.chk(abs(Pg.setting_sec_A - 1.14472) / 1.14472 < 1e-9, 'C4 GEN-51-SI secondary 1.14472 A');
T = T.chk(~isempty(strfind(Pg.basis, 'max-operating-current')) && ~isempty(strfind(Pg.basis, 'Imax-14309A')), 'C4 GEN basis documents max-operating-current Imax-14309A');
T = T.chk(~isempty(strfind(Pg.source, '17171A')) || ~isempty(strfind(Pg.validation, '17171A')), 'C4 GEN convergence with Siemens 17171A noted');
T = T.chk(abs(Pg.setting - 17171) / 17171 < 0.005, 'C4 GEN convergence band vs Siemens baseline <0.5%');
T = T.chk(~strcmp(Pg.curve, P.curve), 'C4 GEN study characteristic differs from DT baseline');
T = T.chk(strcmp(char(Pg.unit), 'A-primary') && strcmp(Pg.assumption_class, 'PRIMARY'), 'C4 GEN unit A-primary, class PRIMARY');
ga = g;
ga.device_id = 'GEN-51-SI';
Pa = phase5b_pickup(ga, FL_GENQ_A, IMIN_PHASE_A);
T = T.chk(abs(Pa.setting - Pg.setting) / Pg.setting < 1e-12, 'C4 GEN-51-SI alias same setting as GEN-51');
tgen = phase5_time(2 * Pg.setting_sec_A, Pg.setting_sec_A, Pg.tms, Pg.curve);
T = T.chk(isfinite(tgen) && tgen > 0 && tgen < 10, 'C4 phase5_time accepts study SI row (finite time)');
gs = R.devices(strcmp(ids, 'GSUT-HV-51'));
ILOAD_GSUT_A = 870.772573866956;
Ps = phase5b_pickup(gs, ILOAD_GSUT_A, IMIN_PHASE_A);
T = T.chk(abs(Ps.setting - 1380) / 1380 < 1e-9, 'C4 GSUT-HV-51 setting 1.2xmax(1150,870.7726)=1380 A');
T = T.chk(abs(Ps.tms - 0.20) < 1e-12, 'C4 GSUT-HV-51 TMS 0.20');
T = T.chk(abs(Ps.setting_sec_A - 1380 / 1600) / (1380 / 1600) < 1e-12, 'C4 GSUT secondary 1380/1600=0.8625 A');
T = T.chk(~isempty(strfind(Ps.basis, 'max(')) && ~isempty(strfind(Ps.source, '1600/1')), 'C4 GSUT basis max() via 1600/1');
gq = R.devices(strcmp(ids, 'GIS-Q0-51'));
ILOAD_Q0_A = 869.956651959241;
Pq = phase5b_pickup(gq, ILOAD_Q0_A, IMIN_PHASE_A);
T = T.chk(abs(Pq.setting - 1.2 * ILOAD_Q0_A) / Pq.setting < 1e-12, 'C4 GIS-Q0-51 setting 1.2x869.956652');
T = T.chk(abs(Pq.tms - 0.20) < 1e-12, 'C4 GIS-Q0-51 TMS 0.20');
T = T.chk(abs(Pq.setting_sec_A - Pq.setting / 1600) / Pq.setting_sec_A < 1e-12, 'C4 GIS secondary Is/1600');
ge = R.devices(strcmp(ids, 'GEN-51N'));
IMIN_EF_A = 7.27200442799167;
Pe = phase5b_pickup(ge, 0, IMIN_EF_A);
T = T.chk(abs(Pe.setting - 5) < 1e-12, 'C4 GEN-51N-SI-STUDY setting 5 A retained');
T = T.chk(strcmp(Pe.assumption_class, 'SENSITIVITY'), 'C4 EF scope SENSITIVITY');
T = T.chk(abs(Pe.tms - 0.15) < 1e-12 && abs(Pe.ef_tms - 0.15) < 1e-12, 'C4 EF TMS 0.15 per master S21');
T = T.chk(abs(Pe.setting_sec_A - 5 / 15000) / (5 / 15000) < 1e-9, 'C4 EF secondary 5/15000');
ge2 = ge;
ge2.device_id = 'GEN-51N-SI-STUDY';
Pe2 = phase5b_pickup(ge2, 0, IMIN_EF_A);
T = T.chk(abs(Pe2.setting - 5) < 1e-12, 'C4 GEN-51N-SI-STUDY alias 5 A');
tef = phase5_time(2 * Pe.setting_sec_A, Pe.setting_sec_A, Pe.tms, Pe.curve);
T = T.chk(isfinite(tef) && tef > 0, 'C4 phase5_time accepts study EF SI row (finite time)');
q50 = R.devices(strcmp(ids, 'GIS-Q0-50'));
try
    phase5b_pickup(q50, ILOAD_Q0_A, IMIN_PHASE_A);
    T = T.chk(false, 'C4 GIS-Q0-50 stays DISABLED');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_pickup:disabled'), 'C4 GIS-Q0-50 DISABLED (TMS never enables; phase5b_pickup:disabled)');
end
ln = R.devices(strcmp(ids, 'LINE-21-note'));
try
    phase5b_pickup(ln, 0, IMIN_PHASE_A);
    T = T.chk(false, 'C4 LINE-21-note has no settings');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'C4 note/boundary error phase5b-prefixed (no stub)');
end
% --- Errors phase5b-prefixed ---
try
    phase5b_pickup(dev, -1, IMIN_PHASE_A);
    T = T.chk(false, 'negative Iload errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'Iload error phase5b-prefixed');
end
try
    phase5b_pickup(struct('device_id', ''), FL_GENQ_A, IMIN_PHASE_A);
    T = T.chk(false, 'empty device_id errors');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b', 7), 'device error phase5b-prefixed');
end
[np, nf] = T.done();
end

