% --- (2) Alias map both ways ---
T = T.chk(strcmp(phase5b_id_aliases('GEN-51-SI'),'GEN-51'), 'alias GEN-51-SI -> GEN-51');
T = T.chk(strcmp(phase5b_id_aliases('GEN-51N-SI-STUDY'),'GEN-51N'), 'alias GEN-51N-SI-STUDY -> GEN-51N');
