T = T.chk(strcmp(phase5b_id_aliases('GEN-51N'),'GEN-51N'), 'canonical GEN-51N idempotent');
T = T.chk(strcmp(phase5b_id_aliases('GEN-51-SIEMENS-BL'),'GEN-51-SIEMENS-BL'), 'baseline idempotent (not an alias)');
