% --- 46 capability note, no pickup invented ---
T = T.chk(any(strcmp(ids,'GEN-46')), 'presence GEN-46');
d46 = R.devices(strcmp(ids,'GEN-46'));
T = T.chk(strcmp(d46.layer,'PHYSICAL') && strcmp(d46.ansi,'46'), 'GEN-46 PHYSICAL 46');
T = T.chk(isnan(d46.pickup_A), 'GEN-46 no pickup invented (NaN)');
