% --- 40/32R/21/78/59/81/24/50-27 presence MISSING ---
miss_ids = {'GEN-40','GEN-32R','GEN-21','GEN-78','GEN-59','GEN-81','GEN-24','GEN-50-27'};
for k = 1:numel(miss_ids)
