    if any(strcmp(ids,miss_ids{k}))
        d = R.devices(strcmp(ids,miss_ids{k}));
        T = T.chk(strcmp(d.layer,'PHYSICAL'), ['PHYSICAL layer: ' miss_ids{k}]);
        T = T.chk(isnan(d.pickup_A), ['MISSING pickup NaN: ' miss_ids{k}]);
