% --- 87B/7SS523; 7SD5221x2; 6MD66 ---
T = T.chk(any(strcmp(ids,'GIS-87B')), 'presence GIS-87B');
b87 = R.devices(strcmp(ids,'GIS-87B'));
T = T.chk(strcmp(b87.layer,'PHYSICAL') && strcmp(b87.ansi,'87B'), 'GIS-87B PHYSICAL 87B');
T = T.chk(~isempty(strfind([b87.provenance ' ' b87.protection_function],'7SS523')), 'GIS-87B 7SS523 trace');
T = T.chk(any(strcmp(ids,'LINE-7SD')), 'presence LINE-7SD');
l7 = R.devices(strcmp(ids,'LINE-7SD'));
T = T.chk(strcmp(l7.layer,'PHYSICAL'), 'LINE-7SD PHYSICAL');
T = T.chk(~isempty(strfind([l7.provenance ' ' l7.protection_function],'7SD5221')), 'LINE-7SD 7SD5221x2 trace');
T = T.chk(any(strcmp(ids,'GIS-6MD66')), 'presence GIS-6MD66');
m66 = R.devices(strcmp(ids,'GIS-6MD66'));
T = T.chk(strcmp(m66.layer,'PHYSICAL') && ~isempty(strfind([m66.provenance ' ' m66.protection_function],'6MD66')), 'GIS-6MD66 bay-control note');
% --- 52G/10BAC10 12.4kA/100kA SOURCE-BACKED ---
T = T.chk(any(strcmp(ids,'GEN-52G')), 'presence GEN-52G');
