z2 = pf('F2'); T = T.chk(numel(z2)==1 && strcmp(z2.ansi,'87T'), 'F2->87T primary mapping');
z3 = pf('F3'); T = T.chk(numel(z3)==1 && strcmp(z3.ansi,'87B'), 'F3->87B primary mapping');
z4 = pf('F4'); T = T.chk(numel(z4)==1 && ~isempty(strfind(z4.ansi,'7SD')), 'F4->7SD primary mapping');
for i = 1:numel(Z)
    T = T.chk(strcmp(Z(i).trip_52G,'NOT-DETERMINABLE'), ['trip_52G NOT-DETERMINABLE: ' Z(i).device_id]);
    T = T.chk(strcmp(Z(i).trip_Q0,'NOT-DETERMINABLE'), ['trip_Q0 NOT-DETERMINABLE: ' Z(i).device_id]);
