    T = T.chk(any(strcmp(ids,Z(i).device_id)), ['zones device in registry: ' Z(i).device_id]);
end
% --- Errors phase5b-prefixed ---
try
    phase5b_zones(1);
    T = T.chk(false, 'phase5b_zones(1) errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'zones error phase5b-prefixed');
end
try
    phase5b_id_aliases();
    T = T.chk(false, 'phase5b_id_aliases() errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'alias error phase5b-prefixed');
end
try
    phase5b_id_aliases('');
    T = T.chk(false, 'alias empty errors');
catch ME
    T = T.chk(strncmp(ME.identifier,'phase5b',7), 'alias empty phase5b-prefixed');
end
[np, nf] = T.done();
end

