IMIN_PHASE_A = 43758.8597559;
cLayer = isscalar(g) && strcmp(g.layer, 'STUDY') && isscalar(bl) && strcmp(bl.layer, 'PHYSICAL');
cDistinct = ~strcmp(g.device_id, bl.device_id);
cAlias = strcmp(phase5b_id_aliases('GEN-51-SI'), 'GEN-51') ...
    && strcmp(phase5b_id_aliases('GEN-51'), 'GEN-51') ...
    && strcmp(phase5b_id_aliases('GEN-51-SIEMENS-BL'), 'GEN-51-SIEMENS-BL');
Pg = phase5b_pickup(g, FL_GENQ_A, IMIN_PHASE_A);
ga = g; ga.device_id = 'GEN-51-SI';
Pa = phase5b_pickup(ga, FL_GENQ_A, IMIN_PHASE_A);
Pb = phase5b_pickup(bl, FL_GENQ_A, IMIN_PHASE_A);
eSet = abs(Pg.setting - 17170.8) / 17170.8;
eAlias = abs(Pa.setting - Pg.setting) / Pg.setting;
cStudy = (abs(Pg.tms - 0.10) < 1e-12) && strcmp(Pg.curve, 'SI') ...
    && islogical(Pg.use_phase5_time) && Pg.use_phase5_time;
cSplit = ~strcmp(Pg.curve, Pb.curve);
cConv = abs(Pg.setting - 17171) / 17171 < 0.005;
try
    q50 = R.devices(strcmp(ids, 'GIS-Q0-50'));
    phase5b_pickup(q50, 869.956651959241, IMIN_PHASE_A);
    disOK = false;
catch ME
    disOK = strcmp(ME.identifier, 'phase5b_pickup:disabled');
end
try
    ln = R.devices(strcmp(ids, 'LINE-21-note'));
    phase5b_pickup(ln, 0, IMIN_PHASE_A);
    noteOK = false;
catch ME
    noteOK = strncmp(ME.identifier, 'phase5b', 7);
end
p = cLayer && cDistinct && cAlias && (eSet < 1e-9) && (eAlias < 1e-12) ...
    && cStudy && cSplit && cConv && disOK && noteOK;
r = max(eSet, eAlias);
n = sprintf(['STUDY GEN-51 (SI/TMS-0.10/inverse-allowed) distinct from PHYSICAL GEN-51-SIEMENS-BL (DT-??/false); ' ...
    'study 17170.8 A (rel %.2g); alias equal (rel %.2g); convergence <0.5%%; Q0-50 DISABLED + note errors ok'], eSet, eAlias);
