K = readtable(Fc, 'Delimiter', ',');
hit = strcmp(K.fault_type, 'LG') & strcmp(K.location, 'F1') ...
    & strcmp(K.caseID, 'LF360_GAT_OUT') & strcmp(K.stage, 'Ikpp') & K.m == 0.5;
if sum(hit) ~= 1
    p = false; r = Inf;
    n = 'B11 missing unique F1-LG-OUT Ikpp m==0.5 contributions row';
    return;
end
rr = K(hit, :);
leg = rr.leg_GEN_kA;
total = rr.Irms_kA;
cLeg = abs(leg - 8.4141) < 1e-4;
cKCL = all([rr.kcl_seq, rr.kcl_ph, rr.kcl_earth] < 1e-9);
A = readtable(Fa, 'Delimiter', ',');
ahit = strcmp(A.fault_type, 'LG') & strcmp(A.location, 'F1') ...
    & strcmp(A.caseID, 'LF360_GAT_OUT') & strcmp(A.through_path, 'GEN_Q') ...
    & strcmp(A.stage, 'Ikpp') & strcmp(A.kind, 'RMS');
ar = A(ahit, :);
anchor = ar.FL_anchor_kA;
cAnchor = abs(anchor - 9.4757) < 1e-3;
cJoin = abs(ar.primary_kA - leg) < 1e-9;
rel = abs(leg - anchor) / anchor;
legover = leg / total;
cEv = (rel > 0.05) && (legover > 100);
locs = tocell(Ti.fault_location); typs = tocell(Ti.fault_type); cases = tocell(Ti.caseID);
irow = Ti(strcmp(locs, 'F1') & strcmp(typs, 'LG') & strcmp(cases, 'LF360_GAT_OUT'), :);
cImp = (height(irow) == 1) && (abs(irow.leg_GEN_kA - leg) < 1e-9);
p = cLeg && cKCL && cAnchor && cJoin && cEv && cImp;
r = abs(leg - 8.4141);
if p
    verdict = 'branch-through-current-magnitude';
else
    verdict = 'BLOCKED-see-evidence';
end
n = sprintf(['F1-LG-OUT leg_GEN %.6f kA (d %.2g vs 8.4141, tol 1e-4); KCL <1e-9; anchor GEN_Q %.4f kA; ' ...
    'rel %.4f (>0.05) leg/total %.1f (>100) verdict %s; import join carries same leg'], leg, r, anchor, rel, legover, verdict);
end

function [p, r, n] = legB12(R)
%LEG B12  No-conflation: no PHYSICAL row carries STUDY numbers and vice versa.
ids = {R.devices.device_id};
viol = 0;
msgs = {};
studyIds = {'GEN-51', 'GEN-51N', 'GSUT-HV-51', 'GIS-Q0-51'};
for k = 1:numel(studyIds)
    d = R.devices(strcmp(ids, studyIds{k}));
    if ~isscalar(d) || ~isnan(d.pickup_A), viol = viol + 1; msgs{end+1} = ['STUDY-NaN-' studyIds{k}]; end
end
for i = 1:numel(R.devices)
    d = R.devices(i);
    if strcmp(d.layer, 'PHYSICAL')
        isSrc = any(strcmp(d.device_id, {'GEN-51-SIEMENS-BL', 'GEN-87G'}));
        if ~isSrc && ~isnan(d.pickup_A), viol = viol + 1; msgs{end+1} = ['PHYS-NaN-' d.device_id]; end
        if ~(isnan(d.tms) && isnan(d.ef_pickup_A) && isnan(d.ef_tms)), viol = viol + 1; msgs{end+1} = ['PHYS-noTMS-' d.device_id]; end
        if ~isempty(strfind(d.protection_function, 'RULE-1.2xMAXLOAD')), viol = viol + 1; msgs{end+1} = ['PHYS-noRULE-' d.device_id]; end
    else
        blob = [d.protection_function ' ' d.provenance];
        if ~isempty(strfind(blob, 'DT-??')) || ~isempty(strfind(blob, 'SIEMENS')) ...
                || ~isempty(strfind(blob, '10BAC10')) || ~isempty(strfind(blob, '7SS523')) ...
                || ~isempty(strfind(blob, '7SD5221'))
            viol = viol + 1; msgs{end+1} = ['STUDY-noPHYS-tokens-' d.device_id];
        end
        if strncmp(d.provenance, 'USER_ASSERTED_PENDING_DOC', 25), viol = viol + 1; msgs{end+1} = ['STUDY-noUSER_ASSERTED-' d.device_id]; end
    end
end
FL_GENQ_A = 9.47574312698307 * 1000;
IMIN_PHASE_A = 43758.8597559;
g = R.devices(strcmp(ids, 'GEN-51'));
bl = R.devices(strcmp(ids, 'GEN-51-SIEMENS-BL'));
Pg = phase5b_pickup(g, FL_GENQ_A, IMIN_PHASE_A);
Pb = phase5b_pickup(bl, FL_GENQ_A, IMIN_PHASE_A);
if ~(strcmp(Pg.curve, 'SI') && Pg.use_phase5_time && strcmp(Pb.curve, 'DT-??') && ~Pb.use_phase5_time && ~strcmp(Pg.curve, Pb.curve))
    viol = viol + 1; msgs{end+1} = 'engine-DT-vs-SI-split';
end
p = (viol == 0);
r = double(viol);
if p
    n = 'cross-scan registry+pickup: STUDY pickups NaN / PHYSICAL non-sourced NaN + TMS/EF NaN; RULE tag STUDY-only; DT-??/SIEMENS/10BAC10/7SS523/7SD5221 PHYSICAL-only; engine DT-??/false vs SI/true split';
else
    n = ['B12 conflations: ' strjoin(msgs, ',')];
end
end

function [p, r, n] = legB13(Ti)
%LEG B13  R0 identity (same anchors and tolerances as v1 R0, v2 path).
locs = tocell(Ti.fault_location); typs = tocell(Ti.fault_type); cases = tocell(Ti.caseID);
a = Ti(strcmp(locs, 'F3') & strcmp(typs, 'LLL') & strcmp(cases, 'LF360_GAT_OUT'), :);
g = Ti(strcmp(locs, 'F1') & strcmp(typs, 'LG') & strcmp(cases, 'LF360_GAT_OUT'), :);
d1 = abs(a.I_primary_kA - 50.5308851865359);
d2 = abs(g.I_primary_kA - 0.00727200442799167);
p = (d1 < 1e-6) && (d2 < 1e-9);
r = max(d1, d2);
n = sprintf('v2 R0 identity (same tolerances as v1 R0): F3-LLL-OUT %.10f kA (d %.2g, tol 1e-6); F1-LG-OUT %.14f kA (d %.2g, tol 1e-9)', ...
    a.I_primary_kA, d1, g.I_primary_kA, d2);
end

