function [np, nf] = test_phase5b_report()
%TEST_PHASE5B_REPORT  Phase-5b Task C13 report rewrite guards (TDD).
%   Scans root PHASE5_FINAL_REPORT.md for:
%     (1) forbidden-string absence (0 hits, case-insensitive);
%     (2) v2 spot numbers matching live results/phase5_protection_v2/ CSVs
%         read with explicit readtable Delimiter (GIS pickup exact value,
%         FAIL-distribution line, duty split, effectiveness split);
%     (3) v1 appendix markers (SUPERSEDED-BY-V2 + frozen v1 numbers).
%   TDD RED note: first run FAILS on the frozen v1 report text (no
%   production-v2 / 17170.8 / SIEMENS-BL / SUPERSEDED-BY-V2 markers).
T = t_case('test_phase5b_report');
root = ashuganj_root();
repPath = fullfile(root, 'PHASE5_FINAL_REPORT.md');
T = T.chk(exist(repPath, 'file') == 2, 'report exists at root');
rep = fileread(repPath);
low = lower(rep);

% --- (1) Forbidden strings, 0 hits (case-insensitive) ---
forbidden = {'actual plant settings', 'commissioned settings', ...
    'siemens settings', 'plant protection failure', ...
    'generator earth-fault protection validated', 'fully realistic', ...
    'exact plant settings', 'iec compliant'};
for k = 1:numel(forbidden)
    T = T.chk(isempty(strfind(low, forbidden{k})), ['forbidden absent: ' forbidden{k}]);
end

% --- (2a) v2 body markers (fail on v1 text by design) ---
T = T.chk(~isempty(strfind(rep, 'production-v2')), 'v2 tag production-v2 present');
T = T.chk(~isempty(strfind(rep, '17170.8')), 'v2 GEN-51-SI pickup 17170.8 present');
T = T.chk(~isempty(strfind(rep, '1043.94798235109')), 'v2 GIS pickup exact value present');
T = T.chk(~isempty(strfind(rep, 'GEN-51-SIEMENS-BL')), 'v2 Siemens DT baseline row present');
T = T.chk(~isempty(strfind(rep, '17171')), 'v2 baseline 17171 present');
T = T.chk(~isempty(strfind(rep, 'phase5b_effectiveness')), 'v2 effectiveness table referenced');
T = T.chk(~isempty(strfind(rep, '1600/1')), 'v2 1600/1 CTs present');
T = T.chk(~isempty(strfind(rep, 'USER_ASSERTED_PENDING_DOC')), 'v2 provenance class present');
T = T.chk(~isempty(strfind(low, 'promotion')), 'USER_ASSERTED_PENDING_DOC promotion rule stated');
T = T.chk(~isempty(strfind(rep, 'Delimiter')), 'readtable Delimiter dialect note present');

% --- (2b) Live v2 settings spot: GIS pickup matches CSV ---
S = readtable(fullfile(root, 'results', 'phase5_protection_v2', 'phase5_relay_settings.csv'), 'Delimiter', ',');
gisRow = strcmp(S.device_id, 'GIS-Q0-51');
T = T.chk(sum(gisRow) == 1, 'v2 settings CSV has one GIS-Q0-51 row');
gisVal = S.setting_A_primary(gisRow);
T = T.chk(abs(gisVal - 1043.94798235109) < 1e-6, 'v2 GIS pickup live value 1043.94798235109');
T = T.chk(~isempty(strfind(rep, '1043.94798235109')), 'report transcribes live v2 GIS pickup');
genRow = strcmp(S.device_id, 'GEN-51');
T = T.chk(abs(S.setting_A_primary(genRow) - 17170.8) < 1e-6, 'v2 GEN-51 live value 17170.8');

% --- (2c) Live v2 coordination distribution matches report line ---
M = readtable(fullfile(root, 'results', 'phase5_protection_v2', 'phase5_coordination_matrix.csv'), 'Delimiter', ',');
nFAIL = sum(strcmp(M.verdict, 'FAIL'));
nNOTRIP = sum(strcmp(M.verdict, 'NO-TRIP'));
nNOPAIR = sum(strcmp(M.verdict, 'NO-PAIR'));
nNOTDET = sum(strcmp(M.verdict, 'NOT DETERMINABLE FROM AVAILABLE DATA'));
nPASS = sum(strcmp(M.verdict, 'PASS'));
T = T.chk(height(M) == 96, 'v2 matrix 96 rows live');
failLine = sprintf('FAIL = %d', nFAIL);
T = T.chk(~isempty(strfind(rep, failLine)), ['report carries live FAIL-distribution line: ' failLine]);
T = T.chk(~isempty(strfind(rep, sprintf('PASS = %d', nPASS))), 'report carries live PASS count');
T = T.chk(~isempty(strfind(rep, sprintf('NO-TRIP = %d', nNOTRIP))), 'report carries live NO-TRIP count');
T = T.chk(nFAIL + nNOTRIP + nNOPAIR + nNOTDET + nPASS == height(M), 'v2 distribution covers all rows');

% --- (2d) Live v2 duty split matches report ---
D = readtable(fullfile(root, 'results', 'phase5_protection_v2', 'phase5_breaker_duty.csv'), 'Delimiter', ',');
nQ0notdet = sum(strcmp(D.breaker_ref, 'Q0') & strcmp(D.verdict, 'NOT DETERMINABLE FROM AVAILABLE DATA'));
n52pass = sum(strcmp(D.breaker_ref, '52G') & strcmp(D.verdict, 'PASS'));
nNOTE = sum(strcmp(D.verdict, 'NOTE'));
T = T.chk(height(D) == 81, 'v2 duty 81 rows live');
T = T.chk(n52pass == 40, 'v2 52G PASS 40 live');
T = T.chk(nQ0notdet == 40, 'v2 Q0 NOT-DET 40 live');
T = T.chk(nNOTE == 1, 'v2 NOTE 1 live');
T = T.chk(~isempty(strfind(rep, '52G')) && ~isempty(strfind(rep, '100 kA')), 'report states 52G 100 kA duty');
T = T.chk(~isempty(strfind(rep, '40 x 52G PASS')) || ~isempty(strfind(rep, '40 PASS')) || ~isempty(strfind(rep, 'PASS = 40')) || ~isempty(strfind(rep, '52G PASS = 40')), 'report carries v2 52G PASS=40 split');

% --- (2e) Live v2 effectiveness split matches report ---
E = readtable(fullfile(root, 'results', 'phase5_protection_v2', 'phase5b_effectiveness.csv'), 'Delimiter', ',');
nAD = sum(strcmp(E.detection, 'ASSERTABLE-DETECT'));
nND = sum(strcmp(E.detection, 'NOT-DETERMINABLE'));
T = T.chk(height(E) == 48, 'v2 effectiveness 48 rows live');
T = T.chk(nAD == 24 && nND == 24, 'v2 effectiveness 24/24 live split');
T = T.chk(~isempty(strfind(rep, 'ASSERTABLE-DETECT')) && ~isempty(strfind(rep, 'NOT-DETERMINABLE')), 'report carries effectiveness vocabulary');
T = T.chk(~isempty(strfind(rep, '87G')) && ~isempty(strfind(rep, '87T')) && ~isempty(strfind(rep, '87B')) && ~isempty(strfind(rep, '7SD')), 'report explains 87G/87T/87B/7SD roles');

% --- (3) v1 appendix markers (fail on v1 body-only text by design) ---
T = T.chk(~isempty(strfind(rep, 'SUPERSEDED-BY-V2')), 'v1 appendix SUPERSEDED-BY-V2 marker present');
T = T.chk(~isempty(strfind(rep, '15023.75')), 'v1 frozen GEN pickup 15023.75 transcribed in appendix');
T = T.chk(~isempty(strfind(rep, '344')), 'v1 suite 344 transcribed in appendix');
T = T.chk(~isempty(strfind(low, 'v1 appendix')), 'v1 appendix section present');

[np, nf] = T.done();
end

