function [np, nf] = test_phase5b_writer()
%TEST_PHASE5B_WRITER  Unit checks for phase5b_writer (Phase-5b Task C11, TDD).
%   Schema + provenance-whitelist + guard checks only; hermetic (synthetic
%   1-2 row tables into a temp dir, no production data, no production run,
%   no effectiveness recompute).
%   Guards asserted:
%     - 10 CSVs (9 v1-parity with v2 schemas + NEW phase5b_effectiveness.csv)
%       + manifest.json + run_log.txt + sha256.txt written;
%     - v2 registry exact 27-col schema (21 v1 + 5 v2 + scope);
%     - duty exact 14-col schema (v1 10 + 2 equipment cols + provenance + scope);
%     - effectiveness locked 13 cols in order;
%     - manifest tag echoes meta.tag; rowCounts carry phase5b_effectiveness_csv;
%     - codeHashes include phase5b_* AND frozen v1 modules used;
%     - sha256.txt covers 12 files (10 CSVs + manifest + run_log);
%     - provenance whitelist: each of SOURCE-BACKED/DERIVED/
%       ENGINEERING_ASSUMPTION/LEGACY/MISSING/USER_ASSERTED_PENDING_DOC passes;
%       any other class errors phase5b_writer:provenance;
%     - empty provenance / empty scope cells error phase5b_writer:provenance;
%     - missing scope column errors phase5b_writer:schema;
%     - assumption_class PRIMARY on a PHYSICAL registry row is LEGAL
%       (C3 concern resolved: yes — writer must not reject it);
%     - frozen phase5_sensitivity.m carries a v1 2000 hard-code
%       (evidence pin for the C11 BLOCKED ruling: driver uses v2-adapted
%       sensitivity, never the frozen module — read-only scan, no modification).
%   All errors are 'phase5b'-prefixed.
T = t_case('test_phase5b_writer');
[tables, meta] = tiny_tables_v2('production-v2');
tmpOut = fullfile(tempdir(), 'phase5b_writer_test');
if exist(tmpOut, 'dir') == 7
    rmdir(tmpOut, 's');
end
W = phase5b_writer(tmpOut, tables, meta);
T = T.chk(isstruct(W) && isfield(W, 'files'), 'writer returns W struct with files');
expCsv = {'phase5_device_registry.csv', 'phase5_relay_settings.csv', ...
    'phase5_fault_inputs.csv', 'phase5_relay_currents.csv', ...
    'phase5_coordination_matrix.csv', 'phase5_coordination_margins.csv', ...
    'phase5_breaker_duty.csv', 'phase5_sensitivity.csv', ...
    'phase5_validation.csv', 'phase5b_effectiveness.csv'};
for k = 1:numel(expCsv)
    T = T.chk(exist(fullfile(tmpOut, expCsv{k}), 'file') == 2, ...
        sprintf('CSV written: %s', expCsv{k}));
end
T = T.chk(exist(fullfile(tmpOut, 'manifest.json'), 'file') == 2, 'manifest.json written');
T = T.chk(exist(fullfile(tmpOut, 'run_log.txt'), 'file') == 2, 'run_log.txt written');
T = T.chk(exist(fullfile(tmpOut, 'sha256.txt'), 'file') == 2, 'sha256.txt written');
% Row-count round trip on three representative tables incl. NEW effectiveness.
R2 = readtable(fullfile(tmpOut, 'phase5_fault_inputs.csv'));
T = T.chk(height(R2) == height(tables.faultInputs), 'fault_inputs row count round-trips');
D2 = readtable(fullfile(tmpOut, 'phase5_breaker_duty.csv'));
T = T.chk(height(D2) == height(tables.duty), 'breaker_duty row count round-trips');
E2 = readtable(fullfile(tmpOut, 'phase5b_effectiveness.csv'));
T = T.chk(height(E2) == height(tables.effectiveness), 'effectiveness row count round-trips');
% Manifest tag echo + v2 rowCounts key + v1-outputs reference.
M = jsondecode(fileread(fullfile(tmpOut, 'manifest.json')));
T = T.chk(strcmp(M.tag, 'production-v2'), 'manifest tag echoes meta.tag production-v2');
T = T.chk(isfield(M.rowCounts, 'phase5b_effectiveness_csv'), 'rowCounts carry phase5b_effectiveness_csv');
T = T.chk(isfield(M.input, 'v1OutputsManifestSha256'), 'manifest input carries v1-outputs reference SHA');
% Code hashes cover phase5b_* AND frozen v1 modules used.
cfiles = {M.codeHashes.file};
T = T.chk(any(strcmp(cfiles, 'phase5b_writer.m')), 'codeHashes include phase5b_writer.m');
T = T.chk(any(strcmp(cfiles, 'phase5b_registry.m')), 'codeHashes include phase5b_registry.m');
T = T.chk(any(strcmp(cfiles, 'phase5_coord.m')), 'codeHashes include frozen phase5_coord.m');
T = T.chk(any(strcmp(cfiles, 'run_phase5b_production.m')), 'codeHashes include run_phase5b_production.m');
% sha256.txt covers 12 files.
sh = strsplit(strtrim(fileread(fullfile(tmpOut, 'sha256.txt'))), '\n');
T = T.chk(numel(sh) == 12, 'sha256.txt covers 10 CSVs + manifest + run_log (12 lines)');
% Provenance whitelist: each legal class passes on a rewrite.
classes = {'SOURCE-BACKED', 'DERIVED', 'ENGINEERING_ASSUMPTION', ...
    'LEGACY', 'MISSING', 'USER_ASSERTED_PENDING_DOC'};
for k = 1:numel(classes)
    ok = tiny_tables_v2('production-v2');
    ok.faultInputs.provenance{1} = [classes{k} ':unit-test-whitelist-probe'];
    try
        phase5b_writer(fullfile(tempdir(), ['phase5b_wl_' classes{k}]), ok, meta);
        T = T.chk(true, sprintf('whitelist class legal: %s', classes{k}));
    catch ME
        T = T.chk(false, sprintf('whitelist class legal: %s (%s)', classes{k}, ME.identifier));
    end
    if exist(fullfile(tempdir(), ['phase5b_wl_' classes{k}]), 'dir') == 7
        rmdir(fullfile(tempdir(), ['phase5b_wl_' classes{k}]), 's');
    end
end
% Illegal provenance class errors phase5b_writer:provenance.
bad = tables;
bad.faultInputs.provenance{1} = 'INVENTED:no-source-fabricated';
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad0'), bad, meta);
    T = T.chk(false, 'invented provenance class errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:provenance'), 'invented class errors phase5b_writer:provenance');
end
% Duty NOTE-row form: legal SOURCE-BACKED prefix with ESTIMATED reference
% in text passes (whitelist checks the class prefix, never the note body).
noteform = tables;
noteform.duty.provenance{1} = ['SOURCE-BACKED:Phase-4-production-import-joined-F3-LLL-total;' ...
    'ESTIMATED:50.00-kA-station-reference-informational-only-never-duty-basis'];
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_noteform'), noteform, meta);
    T = T.chk(true, 'NOTE-row SOURCE-BACKED prefix with ESTIMATED text passes');
catch ME
    T = T.chk(false, sprintf('NOTE-row form passes (%s)', ME.identifier));
end
if exist(fullfile(tempdir(), 'phase5b_writer_noteform'), 'dir') == 7
    rmdir(fullfile(tempdir(), 'phase5b_writer_noteform'), 's');
end
% Provenance guard: empty provenance cell.
bad = tables;
bad.faultInputs.provenance{1} = '';
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad1'), bad, meta);
    T = T.chk(false, 'empty provenance errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:provenance'), 'empty provenance errors phase5b_writer:provenance');
end
% Provenance guard: empty scope cell.
bad2 = tables;
bad2.duty.scope{2} = '   ';
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad2'), bad2, meta);
    T = T.chk(false, 'empty scope errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:provenance'), 'empty scope errors phase5b_writer:provenance');
end
% Schema guard: missing scope column.
bad3 = tables;
bad3.validation = removevars(bad3.validation, 'scope');
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad3'), bad3, meta);
    T = T.chk(false, 'missing scope column errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:schema'), 'missing scope column errors phase5b_writer:schema');
end
% Schema guard: duty missing equipment columns.
bad4 = tables;
bad4.duty = removevars(bad4.duty, {'equipment_rating_kA', 'equipment_basis'});
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad4'), bad4, meta);
    T = T.chk(false, 'duty missing equipment split errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:schema'), 'duty missing equipment split errors phase5b_writer:schema');
end
% Schema guard: effectiveness missing locked column.
bad5 = tables;
bad5.effectiveness = removevars(bad5.effectiveness, 'not_determinable');
try
    phase5b_writer(fullfile(tempdir(), 'phase5b_writer_bad5'), bad5, meta);
    T = T.chk(false, 'effectiveness missing column errors');
catch ME
    T = T.chk(strcmp(ME.identifier, 'phase5b_writer:schema'), 'effectiveness missing column errors phase5b_writer:schema');
end
% C3 concern resolved: assumption_class PRIMARY on PHYSICAL row is legal.
T = T.chk(any(strcmp(tables.registry.layer, 'PHYSICAL') & strcmp(tables.registry.assumption_class, 'PRIMARY')), ...
    'tiny registry carries PHYSICAL + PRIMARY row (C3 concern probe present)');
% BLOCKED-evidence pin (read-only source scan, frozen file never modified):
% frozen phase5_sensitivity hard-codes the v1 2000 CT on its upstream leg,
% so the v2 driver must use v2-adapted sensitivity, never the frozen module.
anchor = which('phase5_sensitivity');
T = T.chk(~isempty(anchor) && exist(anchor, 'file') == 2, 'frozen phase5_sensitivity.m found on path (evidence scan)');
src = fileread(anchor);
T = T.chk(~isempty(strfind(src, '/ 2000')), 'evidence: frozen sensitivity hard-codes / 2000 upstream CT (BLOCKED ruling pinned)');
T = T.chk(~isempty(strfind(src, '2000/1')), 'evidence: frozen sensitivity carries 2000/1 v1 text (BLOCKED ruling pinned)');
if exist(tmpOut, 'dir') == 7
    rmdir(tmpOut, 's');
end
[np, nf] = T.done();
end

