function [np, nf] = test_phase5b_gate()
%TEST_PHASE5B_GATE  Phase-5b Task C14 extended-gate tests (TDD).
%   Locks interface G = phase5b_gate() / G = phase5b_gate(ov):
%   23-predicate read-only consumer of results/phase5_protection_v2/ +
%   PHASE5_FINAL_REPORT.md + results/phase5_protection/ (v1 untouched spot)
%   + results/phase4_fault/production/ (it modifies nothing); prints a
%   checklist; errors phase5b_gate-prefixed on any fail.
%   Optional struct ov overrides shipped tables/report text in-memory only
%   (negative-path injection); recognised fields: faultInputs,
%   relayCurrents, coordMatrix, coordMargins, duty, sensitivity, settings,
%   registry, validation, effectiveness (MATLAB tables), reportText (char),
%   noThrow (logical: return G without erroring).
%   G struct fields: .n (23), .ids, .pass (logical row), .note (cellstr),
%   .npass.
%   P01-P17 are the v1 17 predicates re-pointed at v2 outputs; B01-B06 are
%   the v2 physical predicates (registry-physical, no-2000, dt-flagged,
%   effectiveness, duty-52G, v1-untouched).
T = t_case('test_phase5b_gate');

% --- Live gate on shipped v2 outputs passes 23/23 ---
G = phase5b_gate();
T = T.chk(isstruct(G) && G.n == 23, 'gate returns struct with n=23 predicates');
T = T.chk(all(G.pass), 'live gate passes all 23 predicates on shipped v2 outputs');
T = T.chk(G.npass == 23, 'live gate npass==23');

% --- Predicate table shape locked ---
T = T.chk(numel(G.ids) == 23 && numel(G.note) == 23, 'ids/notes cover 23 predicates');
T = T.chk(any(strcmp(G.ids, 'regression')) && any(strcmp(G.ids, 'report-match')) ...
    && any(strcmp(G.ids, 'no-Phase3/4-change')), 'key v1 predicate ids present');
T = T.chk(any(strcmp(G.ids, 'registry-physical')) && any(strcmp(G.ids, 'no-2000')) ...
    && any(strcmp(G.ids, 'dt-flagged')) && any(strcmp(G.ids, 'effectiveness')) ...
    && any(strcmp(G.ids, 'duty-52G')) && any(strcmp(G.ids, 'v1-untouched')), ...
    'six B predicate ids present');

% --- Negative path 1: synthetic 2000/1 CT row breaks no-2000 ---
root = ashuganj_root();
Rg = readtable(fullfile(root, 'results', 'phase5_protection_v2', ...
    'phase5_device_registry.csv'), 'Delimiter', ',');
Rg.ct_ratio(1) = 2000;
ov = struct('registry', Rg, 'noThrow', true);
Gn = phase5b_gate(ov);
hit = strcmp(Gn.ids, 'no-2000');
T = T.chk(~Gn.pass(hit), 'synthetic 2000 CT fails no-2000 predicate');
T = T.chk(Gn.npass < 23, 'synthetic 2000 CT reduces npass below 23');
try
    phase5b_gate(struct('registry', Rg));
    T = T.chk(false, 'throwing gate must error on synthetic 2000 CT');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_gate', 12), ...
        'gate failure error is phase5b_gate-prefixed');
end

% --- Negative path 2: shifted F3 value breaks regression ---
Fd = readtable(fullfile(root, 'results', 'phase5_protection_v2', ...
    'phase5_fault_inputs.csv'), 'Delimiter', ',');
rF3 = strcmp(Fd.fault_location, 'F3') & strcmp(Fd.fault_type, 'LLL') ...
    & strcmp(Fd.caseID, 'LF360_GAT_OUT');
Fd.I_primary_kA(rF3) = Fd.I_primary_kA(rF3) + 1.0;
Gn2 = phase5b_gate(struct('faultInputs', Fd, 'noThrow', true));
T = T.chk(~Gn2.pass(strcmp(Gn2.ids, 'regression')), ...
    'shifted F3 LLL value fails regression predicate');
try
    phase5b_gate(struct('faultInputs', Fd));
    T = T.chk(false, 'throwing gate must error on shifted F3');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_gate', 12), ...
        'regression failure error is phase5b_gate-prefixed');
end

[np, nf] = T.done();
end

function [np, nf] = test_phase5b_duty()
%TEST_PHASE5B_DUTY  Phase-5b Task C9 duty correction: 52G rows + equipment/interrupting column split.
%   Locked interface under test: D = phase5b_duty(Tthrough, ratings52G)
%   wraps the FROZEN v1 engine phase5_duty (read-only, never modified) for
%   the Q0 block and adds per-(case,loc,type) 52G rows on the GEN_Q branch
%   (leg_GEN_kA) vs 100 kA sym breaking (SOURCE-BACKED ledger
%   GCB-10BAC10-100kA), plus equipment_rating_kA + equipment_basis columns.
%
%   Locked outcomes (frozen production data):
%     Q0 rows: as in v1, rating_kA NaN, verdict NOT DETERMINABLE FROM
%       AVAILABLE DATA (GIS 50 kA short-time withstand is EQUIPMENT
%       WITHSTAND, master S17 SOURCE-BACKED - never an interrupting rating,
%       so it lives ONLY in the equipment columns).
%     52G rows: equipment NaN (no 52G equipment-withstand sourced) +
%       breaker_interrupting_rating 100 kA; F1 LLL OUT GEN 55.0487 kA -> PASS.
%     IN-case max (honest, whatever the data says): F1/F2 LLL IN GEN
%       54.9411 kA -> PASS; the test recomputes the max from live data and
%       pins the observed value loudly (fails on data change by design).
%     Exactly one 50-kA NOTE row retained; its note text carries separate
%       I_fault_system_reference vs equipment_short_circuit_rating fields
%       (spec S9/S12 system-vs-equipment wording).
%
%   TDD RED note: first run fails with undefined function phase5b_duty
%   as required; GREEN after wrapper creation. v1 phase5_duty.m untouched.
T = t_case('test_phase5b_duty');
root = ashuganj_root();

% --- Synthetic through-table (mirrors v1 duty synthetic + leg_GEN_kA) ---
locs  = {'F1'; 'F3'; 'F4'; 'F5'; 'F4'};
typs  = {'LLL'; 'LLL'; 'LLL'; 'LLL'; 'LL'};
cases = {'CASE_A'; 'CASE_A'; 'CASE_A'; 'CASE_A'; 'CASE_A'};
Itot  = [126.21414119005; 50.5308851865359; 51.058; 53.087; 44.215];
lGRID = [72.105; 47.37; 47.946; 49.941; 0.77298];
lHV   = [72.105; 3.2184; 3.1721; 3.2076; 0.77298];
lTOT  = [72.105; 47.37; 51.058; 3.2076; 1.0912e-13];
lB1   = [NaN; NaN; 14.325; NaN; 0.38649];
lB2   = [NaN; NaN; 36.737; NaN; 0.38649];
lGEN  = [55.049; 3.2285; 3.1826; 3.2177; 0.94037];
pk    = [348.255062723563; 129.76; 131.31; 136.0; 113.71];
Tsyn = table(locs, typs, cases, Itot, lGRID, lHV, lTOT, lB1, lB2, lGEN, pk, ...
    'VariableNames', {'fault_location', 'fault_type', 'caseID', 'I_primary_kA', ...
    'leg_GRID_kA', 'leg_GSUT_HV_kA', 'leg_LINE_total_kA', 'leg_LINE_B1_kA', ...
    'leg_LINE_B2_kA', 'leg_GEN_kA', 'r_kappa_ip'});

% --- Module call: default 52G rating (100 kA SOURCE-BACKED ledger) ---
D = phase5b_duty(Tsyn);

% --- Locked 12-col schema: v1 10 + equipment split ---
exp12 = {'location', 'breaker_ref', 'fault_type', 'caseID', 'I_sym_kA', ...
    'I_peak_kA', 'rating_kA', 'basis', 'verdict', 'note', ...
    'equipment_rating_kA', 'equipment_basis'};
T = T.chk(istable(D), 'D is a table');
T = T.chk(isequal(D.Properties.VariableNames, exp12), 'duty exact 12-col schema in locked order');
T = T.chk(~any(strcmp(D.Properties.VariableNames, 't_up_s')) && ...
    ~any(strcmp(D.Properties.VariableNames, 'margin_s')), 'duty stays separate from coordination');

% --- Row partition: n Q0 + n 52G + exactly one NOTE ---
n = height(Tsyn);
isNote = strcmp(D.verdict, 'NOTE');
isQ0 = strcmp(D.breaker_ref, 'Q0') & ~isNote;
is52 = strcmp(D.breaker_ref, '52G');
T = T.chk(sum(isNote) == 1, 'exactly one NOTE row retained');
T = T.chk(sum(isQ0) == n, 'Q0 block has one row per input row');
T = T.chk(sum(is52) == n, '52G block has one row per input row');
T = T.chk(height(D) == 2 * n + 1, 'height = 2n + 1 (Q0 + 52G + NOTE)');

% --- Q0 rows unchanged from v1: rating NaN, NOT DETERMINABLE ---
Q0 = D(isQ0, :);
T = T.chk(all(isnan(Q0.rating_kA)), 'Q0 rating_kA NaN preserved (50 kA never an interrupting rating)');
T = T.chk(all(strcmp(Q0.verdict, 'NOT DETERMINABLE FROM AVAILABLE DATA')), 'Q0 rows NOT DETERMINABLE as in v1');
% Q0 breaker-path identity preserved via frozen engine (F4 3.1721, F1 72.105).
qF4 = Q0(strcmp(Q0.location, 'F4') & strcmp(Q0.fault_type, 'LLL') & strcmp(Q0.caseID, 'CASE_A'), :);
T = T.chk(height(qF4) == 1 && abs(qF4.I_sym_kA - 3.1721) < 1e-9, 'Q0 F4 LLL through-current 3.1721 kA (frozen-engine identity)');
qF1 = Q0(strcmp(Q0.location, 'F1'), :);
T = T.chk(height(qF1) == 1 && abs(qF1.I_sym_kA - 72.105) < 1e-9, 'Q0 F1 LLL through-current 72.105 kA (frozen-engine identity)');

% --- Q0 equipment columns: GIS 50 kA withstand, never interrupting ---
T = T.chk(all(abs(Q0.equipment_rating_kA - 50) < 1e-12), 'Q0 equipment_rating_kA == 50 (GIS short-time withstand)');
T = T.chk(all(~cellfun(@isempty, strfind(Q0.equipment_basis, 'EQUIPMENT WITHSTAND'))), ...
    'Q0 equipment_basis states EQUIPMENT WITHSTAND');
T = T.chk(all(~cellfun(@isempty, strfind(Q0.equipment_basis, 'never interrupting'))), ...
    'Q0 equipment_basis states never interrupting');
T = T.chk(all(~cellfun(@isempty, strfind(Q0.equipment_basis, 'SOURCE-BACKED'))), ...
    'Q0 equipment_basis SOURCE-BACKED (master S17)');

% --- 52G rows: GEN_Q branch vs 100 kA interrupting; equipment NaN ---
G = D(is52, :);
T = T.chk(all(abs(G.rating_kA - 100) < 1e-12), '52G rating_kA == 100 (GCB-10BAC10 sym breaking)');
T = T.chk(all(isnan(G.equipment_rating_kA)), '52G equipment_rating_kA NaN (no 52G equipment-withstand sourced)');
T = T.chk(all(~cellfun(@isempty, strfind(G.basis, 'GCB-10BAC10'))), '52G basis traces GCB-10BAC10 ledger entry');
T = T.chk(all(~cellfun(@isempty, strfind(G.basis, 'SOURCE-BACKED'))), '52G basis SOURCE-BACKED');
gF1 = G(strcmp(G.location, 'F1') & strcmp(G.fault_type, 'LLL') & strcmp(G.caseID, 'CASE_A'), :);
T = T.chk(height(gF1) == 1 && abs(gF1.I_sym_kA - 55.049) < 1e-9, '52G F1 LLL I_sym 55.049 kA (GEN_Q branch, not 126.21 total)');
T = T.chk(strcmp(gF1.verdict{1}, 'PASS'), '52G F1 LLL 55.049 kA <= 100 kA -> PASS');
T = T.chk(abs(gF1.I_peak_kA - 348.255062723563) < 1e-9, '52G peak passthrough informational only');
% 52G equipment basis: no withstand invented, interrupting/equipment split stated.
T = T.chk(all(~cellfun(@isempty, strfind(G.equipment_basis, 'MISSING'))), '52G equipment_basis MISSING (no withstand sourced)');
% Total-current doctrine: 52G never uses the bus total.
T = T.chk(abs(gF1.I_sym_kA - 126.21414119005) > 1, '52G F1 uses GEN_Q branch, never the 126.21 bus total');

% --- GIS-50kA scan: withstand lives ONLY in equipment columns ---
% rating_kA domain over the whole table: NaN (Q0 duty) / 100 (52G) / 50 (NOTE reference only).
rv = D.rating_kA;
T = T.chk(all(isnan(rv) | abs(rv - 100) < 1e-12 | abs(rv - 50) < 1e-12), 'rating_kA domain is NaN/100/50-only');
T = T.chk(all(isnan(rv(isQ0))), 'GIS-50kA never appears as a Q0 interrupting rating (scan)');
T = T.chk(~table_has_str(Q0(:, {'location', 'breaker_ref', 'fault_type', 'caseID', 'basis', 'verdict', 'note'}), '50 kA sym breaking'), ...
    'no 50 kA sym-breaking claim on Q0 rows (scan)');
T = T.chk(~table_has_str(D(:, {'location', 'breaker_ref', 'fault_type', 'caseID', 'rating_kA', 'basis', 'verdict', 'note'}), 'EQUIPMENT WITHSTAND'), ...
    'EQUIPMENT WITHSTAND wording lives only in equipment columns (scan)');

% --- MISSING 52G rating path: [] -> NOT DETERMINABLE, never invented ---
Dm = phase5b_duty(Tsyn, []);
Gm = Dm(strcmp(Dm.breaker_ref, '52G'), :);
T = T.chk(all(strcmp(Gm.verdict, 'NOT DETERMINABLE FROM AVAILABLE DATA')), 'MISSING 52G rating -> NOT DETERMINABLE');
T = T.chk(all(isnan(Gm.rating_kA)), 'MISSING 52G rating -> rating NaN');
T = T.chk(all(~cellfun(@isempty, strfind(Gm.basis, 'MISSING'))), 'MISSING 52G rating -> basis carries MISSING tag');
Q0m = Dm(strcmp(Dm.breaker_ref, 'Q0') & ~strcmp(Dm.verdict, 'NOTE'), :);
T = T.chk(all(isnan(Q0m.rating_kA)) && all(abs(Q0m.equipment_rating_kA - 50) < 1e-12), ...
    'MISSING rating path keeps Q0 rating NaN + equipment 50');

% --- 50-kA NOTE row retained with system-vs-equipment wording ---
nRow = D(isNote, :);
T = T.chk(abs(nRow.I_sym_kA - 50.5308851865359) < 1e-6, 'NOTE row I_sym 50.53 kA (F3 LLL reference)');
T = T.chk(abs(nRow.rating_kA - 50.0) < 1e-12, 'NOTE row estimated reference 50.00 kA retained');
T = T.chk(~strcmp(nRow.verdict{1}, 'PASS') && ~strcmp(nRow.verdict{1}, 'FAIL'), 'NOTE row never PASS/FAIL');
T = T.chk(~isempty(strfind(nRow.note{1}, 'I_fault_system_reference')), 'NOTE note carries I_fault_system_reference field');
T = T.chk(~isempty(strfind(nRow.note{1}, 'equipment_short_circuit_rating')), 'NOTE note carries equipment_short_circuit_rating field');
T = T.chk(abs(nRow.equipment_rating_kA - 50) < 1e-12, 'NOTE equipment_rating_kA 50 (equipment side of the split)');
T = T.chk(all(~cellfun(@isempty, strfind(nRow.equipment_basis, 'EQUIPMENT WITHSTAND'))), 'NOTE equipment_basis states EQUIPMENT WITHSTAND');

% --- Live-data integration (honest backbone leg join, read-only) ---
Ti = phase5_import(root);
T = T.chk(height(Ti) == 40, 'T40 backbone has 40 rows (2x5x4)');
Di = phase5b_duty(Ti);
T = T.chk(height(Di) == 2 * height(Ti) + 1, 'live duty rows = 2x import rows + exactly one NOTE row');
Gi = Di(strcmp(Di.breaker_ref, '52G'), :);
Qi = Di(strcmp(Di.breaker_ref, 'Q0') & ~strcmp(Di.verdict, 'NOTE'), :);
T = T.chk(all(isnan(Qi.rating_kA)), 'live Q0 rating_kA NaN preserved');
T = T.chk(all(abs(Qi.equipment_rating_kA - 50) < 1e-12), 'live Q0 equipment 50');
T = T.chk(all(isnan(Gi.equipment_rating_kA)), 'live 52G equipment NaN');
T = T.chk(all(abs(Gi.rating_kA - 100) < 1e-12), 'live 52G rating 100');
% F1 LLL OUT 52G PASS (55.0487 kA live anchor).
rOUT = Gi(strcmp(Gi.location, 'F1') & strcmp(Gi.fault_type, 'LLL') & strcmp(Gi.caseID, 'LF360_GAT_OUT'), :);
T = T.chk(height(rOUT) == 1, 'live F1 LLL OUT 52G row present');
T = T.chk(abs(rOUT.I_sym_kA - 55.0487) < 1e-3, 'live F1 LLL OUT GEN_Q 55.0487 kA');
T = T.chk(strcmp(rOUT.verdict{1}, 'PASS'), 'live F1 LLL OUT 52G PASS (55.05 kA <= 100 kA)');
% IN-case max documented honestly: recomputed from live data, pinned loudly.
inG = Gi(strcmp(Gi.caseID, 'LF360_GAT_IN'), :).I_sym_kA;
inMax = max(inG);
T = T.chk(abs(inMax - 54.9411) < 1e-3, sprintf('honest IN-case 52G max %.4f kA (F1/F2 LLL IN anchor)', inMax));
hitMax = Gi(strcmp(Gi.caseID, 'LF360_GAT_IN') & abs(Gi.I_sym_kA - inMax) < 1e-9, :);
T = T.chk(all(strcmp(hitMax.verdict, 'PASS')), 'IN-case max row(s) PASS vs 100 kA (honest, never tuned)');
T = T.chk(all(Gi.I_sym_kA <= 100), 'all live 52G duties <= 100 kA (PASS across backbone)');
% Live NOTE row wording.
niRow = Di(strcmp(Di.verdict, 'NOTE'), :);
T = T.chk(height(niRow) == 1 && ~isempty(strfind(niRow.note{1}, 'I_fault_system_reference')) && ...
    ~isempty(strfind(niRow.note{1}, 'equipment_short_circuit_rating')), 'live NOTE row carries split-field wording');

% --- Errors phase5b-prefixed ---
try
    phase5b_duty(table(), []);
    T = T.chk(false, 'empty table must error');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'empty-table error is phase5b_duty-prefixed');
end
try
    phase5b_duty(Tsyn, struct('breaker_ref', 'Q0', 'rating_kA', 50.0, 'source', 'STUDY:x'));
    T = T.chk(false, 'Q0 rating must error (50 kA withstand never an interrupting rating)');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'Q0-rating error is phase5b_duty-prefixed');
end
try
    phase5b_duty(Tsyn, struct('breaker_ref', 'Q9', 'rating_kA', 40.0, 'source', 'STUDY:x'));
    T = T.chk(false, 'Q9 rating must error (disconnectors never duty)');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'Q9-rating error is phase5b_duty-prefixed');
end
try
    TnoGen = removevars(Tsyn, 'leg_GEN_kA');
    phase5b_duty(TnoGen);
    T = T.chk(false, 'missing leg_GEN_kA must error (GEN_Q required for 52G)');
catch ME
    T = T.chk(strncmp(ME.identifier, 'phase5b_duty', 12), 'missing-GEN-leg error is phase5b_duty-prefixed');
end

[np, nf] = T.done();
end

function tf = table_has_str(D, pat)
%TABLE_HAS_STR  True if pattern appears in any variable name or string cell of D.
tf = ~isempty(strfind(strjoin(D.Properties.VariableNames, '|'), pat));
if tf, return; end
for k = 1:numel(D.Properties.VariableNames)
    col = D.(D.Properties.VariableNames{k});
    if iscell(col)
        for i = 1:numel(col)
            v = col{i};
            if (ischar(v) || isstring(v)) && ~isempty(strfind(char(v), pat))
                tf = true; return;
            end
        end
    elseif ischar(col) || isstring(col)
        if ~isempty(strfind(char(col), pat)), tf = true; return; end
    elseif isnumeric(col)
        continue;
    end
end
end

