function [NP, NF] = run_phase5b_tests(varargin)
%RUN_PHASE5B_TESTS  Phase-5b test runner (Phase-5b Task C12).
%   [NP, NF] = RUN_PHASE5B_TESTS() runs every matlab/tests/test_phase5b_*.m
%   suite (discovered via the test_phase5b_ledger anchor on the path, so gap
%   suites are picked up without runner edits) plus the 14-leg
%   phase5b_validate() engine (R0 Phase-4 regression + B01..B13), accumulates
%   passed/failed counts (each validation leg counts one check), and prints
%   'phase5b_tests: NP passed, NF failed'.
%   A suite that errors counts one failure and the runner continues, so one
%   broken suite never hides the rest; the error text stays loud.
%   The frozen v1 runner is never called or modified (see plan global
%   constraints).
%   All errors raised here are 'phase5b'-prefixed.
if nargin ~= 0
    error('phase5b_tests:args', 'usage: [NP, NF] = run_phase5b_tests().');
end
anchor = which('test_phase5b_ledger');
if isempty(anchor)
    error('phase5b_tests:path', 'test_phase5b_ledger not on path (run with addpath(genpath(''matlab''))).');
end
tdir = fileparts(anchor);
list = dir(fullfile(tdir, 'test_phase5b_*.m'));
NP = 0; NF = 0;
for k = 1:numel(list)
    [~, name] = fileparts(list(k).name);
    try
        [np, nf] = feval(name);
        NP = NP + np; NF = NF + nf;
    catch ME
        NF = NF + 1;
        fprintf('  ERROR %s: %s (%s)\n', name, ME.message, ME.identifier);
    end
end
try
    V = phase5b_validate();
    for k = 1:numel(V.legs)
        if V.legs(k).pass
            NP = NP + 1;
        else
            NF = NF + 1;
        end
        if V.legs(k).pass
            st = 'PASS';
        else
            st = 'FAIL';
        end
        fprintf('  %s %s residual=%.6g note=%s\n', st, V.legs(k).id, V.legs(k).residual, V.legs(k).note);
    end
catch ME
    NF = NF + 1;
    fprintf('  ERROR phase5b_validate: %s (%s)\n', ME.message, ME.identifier);
end
fprintf('phase5b_tests: %d passed, %d failed\n', NP, NF);
end

function M = phase5b_mindetect(T40, devices)
%PHASE5B_MINDETECT  Per-CT min-detect over zone-relevant branch currents (Phase-5b Task C6).
%   M = PHASE5B_MINDETECT(T40, devices) replaces the V9 totals-based
%   min-detect with one struct row per (device, element in
%   phase/residual/negseq). Each row carries the minimum BRANCH current
%   over zone-relevant faults, the C4 study pickup (via phase5b_pickup),
%   the margin (min_branch_A / pickup_A) and a verdict:
%     margin >= 1               -> 'DETECT'
%     margin <  1 (determinable) -> 'BLIND-SPOT-HONEST' (non-PASS, never tuned)
%     not determinable           -> 'NOT-DETERMINABLE' (honest, never invented)
%
%   Row fields (locked): device_id, element, zone_locs, branch_tag,
%   n_zone, n_used, min_branch_A, min_loc, min_type, min_case, pickup_A,
%   pickup_src, margin, verdict, determinable, reason.
%
%   Zone relevance (locked): GEN devices <- F1/F2 rows (GEN_Q branch leg
%   for phase; 3I0 = 3x NER series leg for residual; negseq branch NOT
%   DETERMINABLE); GSUT-HV <- F1/F2/F3 rows (GSUT_HV leg); GIS-Q0 <-
%   F3/F4/F5 rows (LINE_Q9 through-convention magnitude: |leg_LINE_total|
%   for non-F4 rows; F4 rows use the same column with the documented
%   caveat that toward-fault B1+B2 sums both infeeds, so the F4 value
%   overstates the GIS outfeed — the GIS min binds at F5 regardless).
%
%   Branch-current doctrine (hardened): ONLY leg_* columns of the
%   phase5_import T40 join are read (C5-pinned branch-through-current
%   semantics). Fault totals are never a proxy for relay current: no
%   fault-point magnitude column is referenced anywhere below.
%
%   Stored production legs are |Ia| magnitudes only (phase4_handoff
%   legRow). Phase-element candidate types are therefore LLL (symmetric:
%   all phases equal |Ia|) and LG (A-phase faulted; B/C ~ 0 per the
%   phase4 LG_branch0 diagnostic): on LL/LLG rows the stored |Ia| is the
%   UNFAULTED-phase current and understates what B/C phase elements see,
%   so LL/LLG phase coverage is recorded NOT-DETERMINABLE-by-type
%   (counted in the reason string, never silently dropped). Residual
%   scope is the LG sensitivity-defining fault (C4 51N study basis
%   must-detect-F1-LG); LLG residual rows are observed-but-out-of-scope
%   and their observed 3I0 minimum is quoted in the reason string as a
%   flagged limitation, never as a verdict input. Negseq branch I2 is
%   unavailable in T40/production CSVs; fault-point sequence current is
%   a total and is never derived per the branch-current doctrine, so
%   every negseq row is NOT-DETERMINABLE.
%
%   Pickups come from the phase5b_pickup C4 rules (registry carries NaN +
%   rule tags; nothing hard-coded here). Load anchors passed to the
%   pickup engine are locked study constants: GEN devices Imax 14309 A
%   (ledger GEN-Imax-14309); GSUT-HV-51 GSUT_HV flow anchor 870.7726 A
%   (rule takes max with rated 1150 A, so 1380 A); GIS-Q0-51 LINE_Q9 flow
%   anchor 869.9567 A; GEN-51N study 0 A (fixed 5 A retained case). The
%   Imin argument is the computed branch minimum itself (settings are
%   load-based, so there is no circularity; validation margins stay
%   consistent). Devices whose pickup errors (DISABLED high-set, notes,
%   boundaries) yield NOT-DETERMINABLE rows quoting the engine reason.
%
%   All errors are 'phase5b'-prefixed.
if nargin ~= 2
    error('phase5b_mindetect:args', 'usage: M = phase5b_mindetect(T40, devices).');
end
if ~istable(T40) || height(T40) < 1
    error('phase5b_mindetect:schema', 'T40 must be a non-empty table (phase5_import backbone).');
end
need = {'fault_location', 'fault_type', 'caseID', 'leg_GEN_kA', ...
    'leg_GSUT_HV_kA', 'leg_LINE_total_kA', 'leg_NER_earth_kA'};
for k = 1:numel(need)
    if ~any(strcmp(T40.Properties.VariableNames, need{k}))
        error('phase5b_mindetect:schema', 'T40 missing required branch column %s.', need{k});
    end
end
if ~isstruct(devices) || isempty(devices) || ~isfield(devices, 'device_id')
    error('phase5b_mindetect:devices', 'devices must be a non-empty struct array with device_id (registry rows).');
end

ELS = {'phase', 'residual', 'negseq'};
M = repmat(emptyRow(), 0, 1);
for d = 1:numel(devices)
    dev = devices(d);
    idraw = dev.device_id;
    if isstring(idraw) && isscalar(idraw)
        idraw = char(idraw);
    end
    if ~ischar(idraw) || isempty(strtrim(idraw))
        error('phase5b_mindetect:devices', 'devices(%d).device_id must be non-empty char.', d);
    end
    id = strtrim(idraw);
    [zone, legCol, zoneTag] = zoneOf(id);
    kind = kindOf(dev, id);
    for e = 1:numel(ELS)
        M(end + 1, 1) = buildRow(T40, dev, id, ELS{e}, zone, legCol, zoneTag, kind); %#ok<AGROW>
    end
end
end

function r = emptyRow()
r = struct('device_id', '', 'element', '', 'zone_locs', '', ...
    'branch_tag', '', 'n_zone', NaN, 'n_used', NaN, 'min_branch_A', NaN, ...
    'min_loc', '', 'min_type', '', 'min_case', '', 'pickup_A', NaN, ...
    'pickup_src', '', 'margin', NaN, 'verdict', 'NOT-DETERMINABLE', ...
    'determinable', false, 'reason', '');
end

function [zone, legCol, zoneTag] = zoneOf(id)
%ZONEOF  Locked zone relevance per device family.
if strncmp(id, 'GEN-', 4)
    zone = {'F1', 'F2'};
    legCol = 'leg_GEN_kA';
    zoneTag = 'F1+F2';
elseif strncmp(id, 'GSUT-HV', 7)
    zone = {'F1', 'F2', 'F3'};
    legCol = 'leg_GSUT_HV_kA';
    zoneTag = 'F1+F2+F3';
elseif strncmp(id, 'GIS-Q0', 6)
    zone = {'F3', 'F4', 'F5'};
    legCol = 'leg_LINE_total_kA';
    zoneTag = 'F3+F4+F5';
else
    zone = {};
    legCol = '';
    zoneTag = '';
end
end

function kind = kindOf(dev, id)
%KINDOF  Phase-OC vs earth-fault device kind (registry device_type wins; id fallback).
if isfield(dev, 'device_type')
    dt = dev.device_type;
    if isstring(dt) && isscalar(dt)
        dt = char(dt);
    end
    if ischar(dt) && strcmp(strtrim(dt), 'ef')
        kind = 'EF';
        return;
    end
    if ischar(dt) && (strcmp(strtrim(dt), 'oc') || strcmp(strtrim(dt), 'oc-instantaneous'))
        kind = 'OC';
        return;
    end
end
if ~isempty(strfind(id, '51N'))
    kind = 'EF';
else
    kind = 'OC';
end
end

function r = buildRow(T40, dev, id, el, zone, legCol, zoneTag, kind)
r = emptyRow();
r.device_id = id;
r.element = el;
r.zone_locs = zoneTag;
if isempty(zone)
    r.branch_tag = 'NOT-APPLICABLE-no-zone-mapping-for-device';
    r.n_zone = 0;
    r.n_used = 0;
    r.reason = sprintf(['zone-not-mapped:%s-has-no-zone-relevant-faults;' ...
        'no-pickup-no-margin-no-verdict-beyond-NOT-DETERMINABLE'], id);
    return;
end
zhit = ismember(T40.fault_location, zone);
r.n_zone = sum(zhit);
if strcmp(el, 'negseq')
    r.branch_tag = 'NOT-APPLICABLE-branch-I2-unavailable-in-T40';
    r.n_used = 0;
    r.reason = sprintf(['negseq-branch-NOT-DETERMINABLE:branch-I2-unavailable-in-T40-' ...
        'production-CSVs;fault-point-sequence-current-is-a-total-never-derived-' ...
        'per-branch-current-doctrine;zone-%s-rows-%d-untouched'], zoneTag, r.n_zone);
    return;
end
if strcmp(el, 'phase') && ~strcmp(kind, 'OC')
    r.branch_tag = 'NOT-APPLICABLE-phase-element-on-EF-device';
    r.n_used = 0;
    r.reason = sprintf(['phase-element-not-applicable:%s-is-earth-fault-device;' ...
        'phase-coverage-NOT-DETERMINABLE;zone-%s-rows-%d-untouched'], id, zoneTag, r.n_zone);
    return;
end
if strcmp(el, 'residual') && ~(strcmp(kind, 'EF') && strcmp(zoneTag, 'F1+F2'))
    r.branch_tag = 'NOT-APPLICABLE-branch-residual-unavailable-in-T40';
    r.n_used = 0;
    if strcmp(kind, 'EF')
        why = 'residual-branch-only-via-NER-series-leg-valid-in-GEN-zone-F1F2';
    else
        why = 'residual-element-not-applicable-to-phase-device';
    end
    r.reason = sprintf(['residual-NOT-DETERMINABLE:%s:%s;' ...
        'zone-%s-rows-%d-untouched'], id, why, zoneTag, r.n_zone);
    return;
end
if strcmp(el, 'phase')
    % |Ia|-representative types only (LL/LLG stored |Ia| is unfaulted-phase).
    typeOK = ismember(T40.fault_type, {'LLL', 'LG'});
    vals = abs(double(T40.(legCol))) * 1000;
    r.branch_tag = sprintf('%s-magnitude-via-%s-SOURCE-BACKED', shortTag(legCol), legCol);
    scopeNote = 'LL-LLG-excluded-unfaulted-phase-Ia-only-in-production-data';
elseif strcmp(el, 'residual')
    % GEN-zone 3I0 from the NER series leg (LG sensitivity scope; LLG observed-only).
    typeOK = strcmp(T40.fault_type, 'LG');
    vals = 3 * abs(double(T40.leg_NER_earth_kA)) * 1000;
    r.branch_tag = '3I0-from-leg_NER_earth_kA-x3-series-SOURCE-BACKED';
    scopeNote = 'LLG-observed-only-out-of-LG-sensitivity-scope';
else
    error('phase5b_mindetect:internal', 'unknown element %s.', el);
end
cand = zhit & typeOK & isfinite(vals);
r.n_used = sum(cand);
if r.n_used < 1
    r.reason = sprintf(['no-finite-branch-current:%s-%s-zone-%s-candidate-rows-0;' ...
        'scope-%s;NOT-DETERMINABLE'], id, el, zoneTag, scopeNote);
    return;
end
[mn, ix] = min(vals(cand));
rows = find(cand);
r.min_branch_A = mn;
r.min_loc = char(T40.fault_location(rows(ix)));
r.min_type = char(T40.fault_type(rows(ix)));
r.min_case = char(T40.caseID(rows(ix)));
nDrop = r.n_zone - r.n_used;
% Observed-but-out-of-scope LLG residual (transparency, never a verdict input).
extra = '';
if strcmp(el, 'residual')
    llg = zhit & strcmp(T40.fault_type, 'LLG') & isfinite(vals);
    if any(llg)
        extra = sprintf(';LLG-observed-3I0-min-%.3fA-out-of-scope-flagged-limitation', ...
            min(vals(llg)));
    end
end
% C4 pickup for the computed branch minimum (settings are load-based).
Iload = loadAnchor(id);
try
    P = phase5b_pickup(dev, Iload, mn);
catch ME
    r.pickup_A = NaN;
    r.pickup_src = 'NOT-DETERMINABLE-pickup-engine-refused';
    r.margin = NaN;
    r.reason = sprintf(['pickup-refused:%s-%s-min-%.3fA-at-%s-%s-%s;' ...
        'engine-%s;NOT-DETERMINABLE'], id, el, mn, r.min_loc, r.min_type, ...
        r.min_case, ME.identifier);
    return;
end
r.pickup_A = P.setting;
r.pickup_src = P.source;
r.margin = mn / P.setting;
r.determinable = true;
if r.margin >= 1
    r.verdict = 'DETECT';
else
    r.verdict = 'BLIND-SPOT-HONEST';
end
r.reason = sprintf(['min-over-%d-of-%d-zone-rows(scope-%s%s);' ...
    'branch-%s=%.3fA-at-%s-%s-%s-vs-pickup-%.3fA(margin-%.4f);verdict-%s'], ...
    r.n_used, r.n_zone, scopeNote, extra, r.branch_tag, mn, ...
    r.min_loc, r.min_type, r.min_case, P.setting, r.margin, r.verdict);
end

function t = shortTag(legCol)
%SHORTTAG  Through-current tag label for a T40 branch column (rename contract: branch-through-current).
switch legCol
    case 'leg_GEN_kA'
        t = 'GEN_Q-branch-through-current';
    case 'leg_GSUT_HV_kA'
        t = 'GSUT_HV-branch-through-current';
    case 'leg_LINE_total_kA'
        t = 'LINE_Q9-through-convention-branch-through-current';
    otherwise
        t = 'branch-through-current';
end
end

function a = loadAnchor(id)
%LOADANCHOR  Locked study load anchors (PRIMARY A) for the C4 pickup rules.
if strncmp(id, 'GEN-51N', 7)
    a = 0;  % fixed 5 A retained sensitive case (load-independent)
elseif strncmp(id, 'GEN-', 4)
    a = 14309;  % generator max operating current (ledger GEN-Imax-14309)
elseif strncmp(id, 'GSUT-HV', 7)
    a = 870.772573866956;  % GSUT_HV flow anchor (rule takes max with rated 1150 A)
elseif strncmp(id, 'GIS-Q0', 6)
    a = 869.956651959241;  % LINE_Q9 flow anchor from ct_data FL_anchor
else
    a = 0;
end
end

function S = phase5b_tcc(varargin)
%PHASE5B_TCC  Two-class TCC plots: physical DT vs study SI (Phase-5b Task C10).
%   S = PHASE5B_TCC() writes two headless figures under v2 plots:
%     results/phase5_protection_v2/plots/tcc_physical.png  Class A physical:
%       GEN definite-time I> vertical at 17171 A primary (1.1447 A via
%       15000/1) + horizontal 3 s line DASHED and labelled ?? 
%       PENDING-COORDINATION (never solid); 87G pickup band marker at
%       0.20pu approx 2403.8 A (vertical band, no curve invented).
%     results/phase5_protection_v2/plots/tcc_study.png  Class B study:
%       SI curves TMS 0.20 with v2 pickups via 1600/1 CTs (GEN 17170.8 A,
%       GSUT 1380 A, GIS 1.2xFL formula) using frozen phase5_curve
%       read-only (never hard-coded times).
%   S = PHASE5B_TCC(outDir) writes into outDir; S = PHASE5B_TCC(outDir, root)
%   resolves v2 registry against root (default ashuganj_root()).
%   Curves come from the locked library only: settings via PHASE5B_REGISTRY
%   + PHASE5B_PICKUP (baseline DT + study SI rules), times via PHASE5_CURVE
%   / PHASE5_TIME (never hard-coded). No maker strings in titles/labels/
%   footers (study values only). Classes in SEPARATE files. Figures are
%   headless-safe (Visible off). All errors are phase5b-prefixed.
if nargin == 0
    root = ashuganj_root();
    outDir = fullfile(root, 'results', 'phase5_protection_v2', 'plots');
elseif nargin == 1
    outDir = varargin{1};
    root = ashuganj_root();
elseif nargin == 2
    outDir = varargin{1};
    root = varargin{2};
else
    error('phase5b_tcc:args', 'usage: S = phase5b_tcc() or phase5b_tcc(outDir) or phase5b_tcc(outDir, root).');
end
if isstring(outDir) && isscalar(outDir), outDir = char(outDir); end
if isstring(root) && isscalar(root), root = char(root); end
if ~ischar(outDir) || isempty(strtrim(outDir))
    error('phase5b_tcc:args', 'outDir must be a non-empty path (char).');
end
if ~ischar(root) || isempty(strtrim(root))
    error('phase5b_tcc:args', 'root must be a non-empty project-root path (char).');
end
if exist(root, 'dir') ~= 7
    error('phase5b_tcc:root', 'project root not found: %s', root);
end
if exist(outDir, 'dir') ~= 7
    [okMk, msgMk] = mkdir(outDir);
    if ~okMk
        error('phase5b_tcc:mkdir', 'cannot create outDir %s (%s).', outDir, msgMk);
    end
end
% --- v2 registry + pickup engine (live, never hard-coded) ---
R = phase5b_registry();
bl = find_by_ansi_layer(R.devices, '50/51-DT', 'PHYSICAL');
d87 = find_by_ansi_layer(R.devices, '87G', 'PHYSICAL');
FL_GENQ_A = 9.47574312698307 * 1000;
IMIN_PHASE_A = 43758.8597559;
Pb = phase5b_pickup(bl, FL_GENQ_A, IMIN_PHASE_A);
dt_Is_prim = Pb.setting;
dt_Is_sec = Pb.setting_sec_A;
tdef_s = Pb.tdef;
pickup_87G_A = double(d87.pickup_A);
pickup_87G_pu = 0.20;
% Study anchors (documented FL anchors; settings recomputed live below).
ILOAD_GSUT_A = 870.772573866956;
ILOAD_Q0_A = 869.956651959241;
dGen = find_by_id(R.devices, 'GEN-51');
dHv = find_by_id(R.devices, 'GSUT-HV-51');
dQ0 = find_by_id(R.devices, 'GIS-Q0-51');
Pg = phase5b_pickup(dGen, FL_GENQ_A, IMIN_PHASE_A);
Ph = phase5b_pickup(dHv, ILOAD_GSUT_A, IMIN_PHASE_A);
Pq = phase5b_pickup(dQ0, ILOAD_Q0_A, IMIN_PHASE_A);
sGen = mk_study_setting('GEN-51', dGen, Pg);
sHv = mk_study_setting('GSUT-HV-51', dHv, Ph);
sQ0 = mk_study_setting('GIS-Q0-51', dQ0, Pq);
study_settings = [sGen, sHv, sQ0];
study_times = zeros(1, 3);
for k = 1:3
    s = study_settings(k);
    study_times(k) = phase5_time(2*s.pickup_sec, s.pickup_sec, s.TMS, s.curve);
end
% --- Class A physical figure ---
dt_label = sprintf('GEN DT I> | CT 15000/1 | Is %.4g A-prim (%.4g A-sec) | DT-?? ?? PENDING-COORDINATION', dt_Is_prim, dt_Is_sec);
tdef_label = sprintf('tdef %.2f s ?? PENDING-COORDINATION (dashed, never solid)', tdef_s);
band_label = sprintf('GEN 87G pickup band 0.20pu approx %.1f A-prim (no curve invented)', pickup_87G_A);
physical_labels = {dt_label, tdef_label, band_label};
physical_title = 'Phase-5b physical TCC (DT baseline + 87G band, ?? PENDING-COORDINATION)';
physical_foot = {'PHYSICAL baseline: DT I> ON, inverse disabled; timing NOT-DETERMINABLE ?? PENDING-COORDINATION', ...
    '87G start 0.20pu band only, no curve invented; trip paths NOT-DETERMINABLE'};
physPng = fullfile(outDir, 'tcc_physical.png');
draw_physical(dt_Is_prim, tdef_s, pickup_87G_A, dt_label, tdef_label, band_label, physical_title, physical_foot, physPng);
% --- Class B study figure ---
study_labels = cell(1, 3);
for k = 1:3
    s = study_settings(k);
    study_labels{k} = sprintf('%s | ANSI 51 OC | CT %.0f/1 | Is %.4g A-prim (%.4g A-sec) | TMS %.4g | %s', ...
        s.device_id, s.ct, s.pickup_prim, s.pickup_sec, s.TMS, s.curve);
end
study_title = 'Phase-5b study TCC (SI curves TMS 0.20, v2 pickups)';
study_foot = {'STUDY SI curves TMS 0.20 via 1600/1 CTs (GSUT/GIS) + 15000/1 GEN; IEC 60255 study values', ...
    'Branch-current doctrine; CTI 0.3 s not shown'};
studyPng = fullfile(outDir, 'tcc_study.png');
draw_study(study_settings, study_labels, study_title, study_foot, studyPng);
S = struct('physical_png', physPng, 'study_png', studyPng, ...
    'physical_title', physical_title, 'study_title', study_title, ...
    'physical_labels', {physical_labels}, 'study_labels', {study_labels}, ...
    'physical_foot', {physical_foot}, 'study_foot', {study_foot}, ...
    'dt_Is_prim', dt_Is_prim, 'dt_Is_sec', dt_Is_sec, 'tdef_s', tdef_s, ...
    'dt_label', dt_label, 'tdef_label', tdef_label, ...
    'dt_vline_style', '-', 'dt_hline_style', '--', ...
    'pickup_87G_A', pickup_87G_A, 'pickup_87G_pu', pickup_87G_pu, ...
    'study_settings', study_settings, 'study_times', study_times);
end

function d = find_by_id(devices, id)
d = [];
for k = 1:numel(devices)
    did = devices(k).device_id;
    if isstring(did) && isscalar(did), did = char(did); end
    if ischar(did) && strcmp(strtrim(did), id), d = devices(k); return; end
end
if isempty(d)
    error('phase5b_tcc:devices', 'device %s not found in phase5b_registry.', id);
end
end

function d = find_by_ansi_layer(devices, ansiWant, layerWant)
d = [];
for k = 1:numel(devices)
    a = devices(k).ansi;
    if isstring(a) && isscalar(a), a = char(a); end
    L = devices(k).layer;
    if isstring(L) && isscalar(L), L = char(L); end
    if ischar(a) && ischar(L) && strcmp(strtrim(a), ansiWant) && strcmp(strtrim(L), layerWant)
        d = devices(k); return;
    end
end
if isempty(d)
    error('phase5b_tcc:devices', 'ansi %s layer %s not found in phase5b_registry.', ansiWant, layerWant);
end
end

function s = mk_study_setting(id, devRow, P)
ct = double(devRow.ct_ratio);
if ~(isscalar(ct) && isfinite(ct) && ct > 0)
    error('phase5b_tcc:ct', 'device %s needs finite ct_ratio > 0 (protection CT).', id);
end
s = struct('device_id', id, 'pickup_prim', double(P.setting), ...
    'pickup_sec', double(P.setting_sec_A), 'TMS', double(P.tms), ...
    'curve', char(P.curve), 'ct', ct);
end

function draw_physical(IsPrim, tdef, bandA, dtLabel, tdefLabel, bandLabel, titleStr, footStr, pngPath)
xmin = 500;
xmax = 2e6;
yl = [0.1, 30];
fig = figure('Visible', 'off', 'Color', 'white');
hold on;
% DT vertical (solid) at Is.
loglog([IsPrim, IsPrim], yl, '-', 'Color', [0 0.4470 0.7410], 'LineWidth', 1.6);
text(IsPrim, yl(2), ['  ' dtLabel], 'Color', [0 0.4470 0.7410], 'FontSize', 7, 'VerticalAlignment', 'top', 'Interpreter', 'none');
% tdef horizontal DASHED at 3 s (never solid by contract).
loglog([xmin, xmax], [tdef, tdef], '--', 'Color', [0.8500 0.3250 0.0980], 'LineWidth', 1.6);
text(xmax*0.5, tdef*1.15, ['  ' tdefLabel], 'Color', [0.8500 0.3250 0.0980], 'FontSize', 7, 'Interpreter', 'none');
% 87G band marker (dotted vertical, no curve invented).
loglog([bandA, bandA], yl, ':', 'Color', [0.4660 0.6740 0.1880], 'LineWidth', 1.4);
text(bandA, yl(2)*0.35, ['  ' bandLabel], 'Color', [0.4660 0.6740 0.1880], 'FontSize', 7, 'Interpreter', 'none');
set(gca, 'XScale', 'log', 'YScale', 'log');
xlabel('Current, A primary (log scale)');
ylabel('Time, s (log scale)');
title(titleStr, 'Interpreter', 'none');
legend({dtLabel, tdefLabel, bandLabel}, 'Location', 'best', 'Interpreter', 'none', 'FontSize', 7);
grid on;
xlim([xmin, xmax]);
ylim(yl);
text(xmax*0.98, yl(2)*0.7, footStr, 'FontSize', 7, ...
    'VerticalAlignment', 'top', 'HorizontalAlignment', 'right', ...
    'Interpreter', 'none');
print(fig, pngPath, '-dpng');
close(fig);
if exist(pngPath, 'file') ~= 2
    error('phase5b_tcc:write', 'TCC PNG not written: %s', pngPath);
end
end

function draw_study(settings, labels, titleStr, footStr, pngPath)
n = numel(settings);
IsAll = zeros(1, n);
for k = 1:n
    IsAll(k) = settings(k).pickup_prim;
end
xmin = min(IsAll) * 0.5;
xmax = max(IsAll) * 100;
if ~(isfinite(xmin) && isfinite(xmax) && xmin > 0 && xmax > xmin)
    error('phase5b_tcc:limits', 'non-finite TCC current axis limits.');
end
fig = figure('Visible', 'off', 'Color', 'white');
hold on;
cols = lines(n);
for k = 1:n
    s = settings(k);
    Is = s.pickup_prim;
    lo = Is * 1.005;
    hi = Is * 100;
    I = logspace(log10(lo), log10(hi), 240);
    M = I / Is;
    t = phase5_curve(M, s.curve, s.TMS);
    loglog(I, t, 'Color', cols(k, :), 'LineWidth', 1.6);
end
yl = [0.01, 100];
for k = 1:n
    loglog([IsAll(k), IsAll(k)], yl, '--', 'Color', cols(k, :), 'LineWidth', 1.0);
    if k == 1
        py = yl(2);
    else
        py = yl(2) * 0.35;
    end
    text(IsAll(k), py, sprintf('  Is %s', settings(k).device_id), ...
        'Color', cols(k, :), 'FontSize', 8, 'VerticalAlignment', 'top');
end
set(gca, 'XScale', 'log', 'YScale', 'log');
xlabel('Current, A primary (log scale)');
ylabel('Time, s (log scale)');
title(titleStr, 'Interpreter', 'none');
legend(labels, 'Location', 'best', 'Interpreter', 'none', 'FontSize', 7);
grid on;
xlim([xmin, xmax]);
ylim(yl);
text(xmax*0.98, yl(2)*0.7, footStr, 'FontSize', 7, ...
    'VerticalAlignment', 'top', 'HorizontalAlignment', 'right', ...
    'Interpreter', 'none');
print(fig, pngPath, '-dpng');
close(fig);
if exist(pngPath, 'file') ~= 2
    error('phase5b_tcc:write', 'TCC PNG not written: %s', pngPath);
end
end

